window.BOOK_DATA = {"schemaVersion":2,"id":"ancient-japan-chapter-01","title":"Chapter 1 — The Earliest Societies in Japan","language":"en","catalogs":{"maps":[{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-islands","showProvinces":false,"scene":"islands","period":"chapter-01","sitePeriods":[],"date":-20000,"accent":"#5F7882","alt":"Scalable map of the changing Pleistocene archipelago and its principal crossing corridors.","view":{"bounds":[[119.0,26.7],[145.0,46.0]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"terrain","label":"Relief and submerged margin","detail":"Modern terrain provides orientation; the routes summarize changing Pleistocene approaches."},{"symbol":"gateway","label":"Maritime or landward gateway","detail":"Gateways mark broad approaches, not surveyed points of entry."},{"symbol":"route-inferred","label":"Reconstructed movement corridor","detail":"Dashed lines show plausible corridors whose use and chronology varied."}],"metadata":{"slug":"1-islands","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Islands emerging","evidenceFrame":"archaeological and geological synthesis"},"id":"map-1-islands","src":"../maps/scenes/1-islands.webp","standing":false,"title":"Islands Emerging","project":"projects/chapter-01/01_islands.qgz","fallback":"../maps/scenes/1-islands.webp","sections":["01.02"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Pleistocene shelves, straits, animal ranges, and the first crossing corridors","caption":"Lower Pleistocene sea levels broadened coastal plains and altered the shape of the archipelago, but they did not erase every strait. The marked corridors frame the plausible northern, western, and southern approaches by which people, animals, and materials could move; they are comparative pathways, not a claim for one proven migration route.","evidence":"Geological and archaeological synthesis; corridors are approximate.","sceneTiles":"qgis-scenes/ch01/islands/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/islands/{z}/{x}/{y}.webp","renderBounds":[118.5,24.0,149.0,48.5]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-paleolithic","showProvinces":false,"scene":"paleolithic","period":"chapter-01","sitePeriods":[],"date":-28000,"accent":"#65717A","alt":"Scalable map of Paleolithic sites, stone movement, changing environments, and early pottery locations.","view":{"bounds":[[126.5,30.5],[143.5,43.0]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"settlement","label":"Occupation or excavation site","detail":"Large symbols are principal paragraph anchors; smaller symbols provide comparison."},{"symbol":"production","label":"Stone or ceramic evidence","detail":"The hexagon identifies a source, workshop, or technically important find."},{"symbol":"route-inferred","label":"Movement or exchange corridor","detail":"Dashed lines are schematic and do not represent a single journey."},{"symbol":"terrain","label":"Relief and water","detail":"Terrain explains access and movement but does not mark a historical boundary."}],"metadata":{"slug":"1-paleolithic","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Paleolithic movement","evidenceFrame":"archaeological evidence"},"id":"map-1-paleolithic","src":"../maps/scenes/1-paleolithic.webp","standing":false,"title":"Paleolithic Movement","project":"projects/chapter-01/02_paleolithic.qgz","fallback":"../maps/scenes/1-paleolithic.webp","sections":["01.03","01.04"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Occupation sites, volcanic landscapes, obsidian travel, and the Mesolithic turn","caption":"Selected occupation sites place Paleolithic communities within volcanic, coastal, and upland environments rather than along a single advancing frontier. Obsidian connections reveal movement across considerable distances, while the earliest pottery locations mark a later technological transition whose timing and regional meaning were uneven.","evidence":"Archaeological evidence; disputed early claims are marked separately.","sceneTiles":"qgis-scenes/ch01/paleolithic/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/paleolithic/{z}/{x}/{y}.webp","renderBounds":[123.44,27.75,146.56,45.75]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-jomon-coasts","showProvinces":false,"scene":"jomon-coasts","period":"chapter-01","sitePeriods":[],"date":-5000,"accent":"#9A654B","alt":"Scalable map of early Jomon coastal settlements, shell mounds, villages, and plant-use sites.","view":{"bounds":[[127.5,30.5],[143.5,42.5]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"settlement","label":"Settlement or shell-mound site","detail":"Symbol size and label prominence express importance to the current passage."},{"symbol":"zone","label":"Broad archaeological concentration","detail":"A soft tint indicates a long-lived cultural field rather than a bounded people."},{"symbol":"route-inferred","label":"Coastal connection","detail":"The route summarizes repeated travel and exchange, not a permanent road."},{"symbol":"terrain","label":"Coast, relief, and water","detail":"The physical base remains deliberately quieter than the historical layer."}],"metadata":{"slug":"1-jomon-coasts","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Jomon coasts","evidenceFrame":"archaeological and environmental evidence"},"id":"map-1-jomon-coasts","src":"../maps/scenes/1-jomon-coasts.webp","standing":false,"title":"Jomon Coasts","project":"projects/chapter-01/03_jomon-coasts.qgz","fallback":"../maps/scenes/1-jomon-coasts.webp","sections":["01.05","01.06"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Shoreline change, shell mounds, durable villages, and plant-rich economies","caption":"Postglacial sea rise created bays, inlets, and productive shorelines around which many Early Jomon communities established durable settlements. Shell mounds and plant-use sites show that coastal abundance belonged to mixed economies joining fishing, gathering, woodland management, craft, and inland exchange.","evidence":"Archaeological and environmental evidence; modern coasts provide orientation only.","sceneTiles":"qgis-scenes/ch01/jomon-coasts/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/jomon-coasts/{z}/{x}/{y}.webp","renderBounds":[124.62,27.86,146.38,45.14]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-jomon-highlands","showProvinces":false,"scene":"jomon-highlands","period":"chapter-01","sitePeriods":[],"date":-3000,"accent":"#A36C4D","alt":"Scalable close map of the Middle Jomon highlands, springs, obsidian routes, and principal settlements.","view":{"bounds":[[136.7,34.5],[140.5,37.5]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"settlement","label":"Highland settlement","detail":"Filled circles identify settlement anchors; size expresses narrative importance."},{"symbol":"production","label":"Craft or material source","detail":"Hexagons identify places important for pottery, obsidian, or specialized production."},{"symbol":"route-inferred","label":"Exchange connection","detail":"Dashed umber lines show generalized movement between mountain and plain."},{"symbol":"zone","label":"Highland concentration","detail":"The zone is interpretive and changes across the long Middle Jomon sequence."}],"metadata":{"slug":"1-jomon-highlands","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Middle Jomon highlands","evidenceFrame":"archaeological synthesis"},"id":"map-1-jomon-highlands","src":"../maps/scenes/1-jomon-highlands.webp","standing":false,"title":"The Middle Jomon Highlands","project":"projects/chapter-01/04_jomon-highlands.qgz","fallback":"../maps/scenes/1-jomon-highlands.webp","sections":["01.07","01.08"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Springs, forest harvests, obsidian, pottery, ritual, and mountain-plain exchange","caption":"The close view reveals why the central highlands could sustain unusually large Middle Jomon settlements: reliable springs, forest harvests, workable terraces, and access to obsidian sources converged within a compact landscape. Connection lines summarize repeated exchange between mountains and plains rather than surveyed roads.","evidence":"Archaeological synthesis; exchange lines summarize repeated movement.","sceneTiles":"qgis-scenes/ch01/jomon-highlands/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/jomon-highlands/{z}/{x}/{y}.webp","renderBounds":[136.016,33.84,141.184,38.16]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-late-jomon","showProvinces":false,"scene":"late-jomon","period":"chapter-01","sitePeriods":[],"date":-800,"accent":"#8C674F","alt":"Scalable map of Late and Final Jomon coastal networks, northern concentrations, ritual places, and exchange.","view":{"bounds":[[126.0,30.0],[144.0,44.5]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"settlement","label":"Settlement or gathering place","detail":"Principal sites are labeled first; contextual sites appear during enlargement."},{"symbol":"burial","label":"Mortuary or ceremonial place","detail":"Diamonds distinguish cemeteries, stone circles, and enduring ritual grounds."},{"symbol":"zone","label":"Regional concentration","detail":"Translucent fields summarize distributions rather than political borders."},{"symbol":"route-inferred","label":"Exchange network","detail":"Dashed lines indicate repeated movement of materials and knowledge."}],"metadata":{"slug":"1-late-jomon","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Late and Final Jomon","evidenceFrame":"archaeological synthesis"},"id":"map-1-late-jomon","src":"../maps/scenes/1-late-jomon.webp","standing":false,"title":"Late And Final Jomon Networks","project":"projects/chapter-01/05_late-jomon.qgz","fallback":"../maps/scenes/1-late-jomon.webp","sections":["01.09","01.10","01.11","01.12"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Highland contraction, renewed coasts, seasonal travel, northern craft, and ritual places","caption":"As many central highland settlements contracted, population and activity became more prominent along coasts, lower valleys, and the richly connected north. The map brings seasonal movement, craft centers, ritual places, and exchange into one field so that change appears as regional reorganization rather than a uniform collapse.","evidence":"Archaeological synthesis; concentration fields are not political borders.","sceneTiles":"qgis-scenes/ch01/late-jomon/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/late-jomon/{z}/{x}/{y}.webp","renderBounds":[122.76,26.81,147.24,47.69]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-rice","showProvinces":false,"scene":"rice","period":"chapter-01","sitePeriods":[],"date":-700,"accent":"#B18A45","alt":"Scalable map of the Korean Strait, the northern Kyushu rice core, and uneven eastward adoption.","view":{"bounds":[[126.5,29.5],[139.2,37.2]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"gateway","label":"Strait gateway","detail":"Gateway symbols emphasize Tsushima, Iki, and northern Kyushu without drawing a political boundary."},{"symbol":"settlement","label":"Agricultural community","detail":"Sites combine fields, settlement, storage, burial, or mixed subsistence in different proportions."},{"symbol":"route-inferred","label":"Phased adoption corridor","detail":"The broad dashed line records uneven movement over centuries, not one advancing front."},{"symbol":"zone","label":"Early rice core or transition","detail":"Tint indicates an archaeological concentration whose dates vary by region."}],"metadata":{"slug":"1-rice","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Rice through the straits","evidenceFrame":"archaeological and environmental evidence"},"id":"map-1-rice","src":"../maps/scenes/1-rice.webp","standing":false,"title":"Rice Through The Straits","project":"projects/chapter-01/06_rice.qgz","fallback":"../maps/scenes/1-rice.webp","sections":["01.13","01.14","01.15","01.16"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Northern Kyushu gateways, early fields, mixed subsistence, and uneven eastward adoption","caption":"Wet-rice cultivation first became established in northern Kyushu through maritime connections across the Korean Strait, then moved eastward through communities that adopted and adapted it at different rates. The mapped sequence emphasizes mixed subsistence and local choice; it does not depict a single wave replacing the archipelago's existing population.","evidence":"Archaeological and environmental evidence; diffusion was phased and uneven.","sceneTiles":"qgis-scenes/ch01/rice/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/rice/{z}/{x}/{y}.webp","renderBounds":[124.214,27.806,141.486,38.894]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-yayoi","showProvinces":false,"scene":"yayoi","period":"chapter-01","sitePeriods":[],"date":50,"accent":"#B18A45","alt":"Scalable map of Yayoi settlements, cemeteries, defended villages, fields, and regional centers.","view":{"bounds":[[129.0,30.5],[141.0,38.0]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"settlement","label":"Settlement","detail":"Circles identify villages and habitation sites; scale reflects relevance to the passage."},{"symbol":"burial","label":"Cemetery or elite burial","detail":"Diamonds distinguish mortuary evidence from habitation."},{"symbol":"production","label":"Production or storage center","detail":"Hexagons identify craft, agricultural, or material-production evidence."},{"symbol":"zone","label":"Regional development","detail":"Soft areas show overlapping archaeological patterns rather than fixed polities."}],"metadata":{"slug":"1-yayoi","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Yayoi landscapes","evidenceFrame":"archaeological evidence"},"id":"map-1-yayoi","src":"../maps/scenes/1-yayoi.webp","standing":false,"title":"Yayoi Landscapes","project":"projects/chapter-01/07_yayoi.qgz","fallback":"../maps/scenes/1-yayoi.webp","sections":["01.17","01.18","01.19","01.20"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Villages, fields, burials, iron tools, managed water, defended places, and hierarchy","caption":"Settlements, paddies, cemeteries, production places, and defended sites show how agriculture reorganized land, water, labor, and social difference. Their distribution reveals several regional trajectories operating at once, from northern Kyushu and the Inland Sea to Kinki and the eastern plains, without implying fixed political borders.","evidence":"Archaeological evidence; regional patterns overlap in time and space.","sceneTiles":"qgis-scenes/ch01/yayoi/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/yayoi/{z}/{x}/{y}.webp","renderBounds":[126.84,28.85,143.16,39.65]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-bronze","showProvinces":false,"scene":"bronze","period":"chapter-01","sitePeriods":[],"date":150,"accent":"#A8753F","alt":"Scalable map of Yayoi bronze workshops, caches, weapon and bell concentrations, and maritime metal supply.","view":{"bounds":[[128.5,31.0],[139.0,37.0]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"production","label":"Workshop or bronze cache","detail":"Hexagons distinguish production and deliberate deposition from ordinary settlement."},{"symbol":"zone","label":"Overlapping bronze concentration","detail":"The fields are diachronic distributions, not rival states with fixed borders."},{"symbol":"route-inferred","label":"Metal-supply connection","detail":"Dashed lines summarize maritime acquisition and inland recasting."},{"symbol":"settlement","label":"Supporting settlement","detail":"Smaller neutral anchors provide geographical orientation."}],"metadata":{"slug":"1-bronze","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Bronze geographies","evidenceFrame":"archaeological and scientific evidence"},"id":"map-1-bronze","src":"../maps/scenes/1-bronze.webp","standing":false,"title":"Bronze Geographies","project":"projects/chapter-01/08_bronze.qgz","fallback":"../maps/scenes/1-bronze.webp","sections":["01.21","01.22","01.23"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Weapons, bells, foundries, ritual deposits, maritime supply, and overlapping regional power","caption":"Bronze workshops and ritual deposits expose overlapping material geographies: weapons and mirrors were especially prominent in parts of the west, while bells became more concentrated farther east. The patterns changed through time, and the maritime links indicate channels of metal, technique, and exchange rather than territories controlled by a single authority.","evidence":"Archaeological and scientific evidence; distribution fields are diachronic.","sceneTiles":"qgis-scenes/ch01/bronze/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/bronze/{z}/{x}/{y}.webp","renderBounds":[126.61,29.68,140.89,38.32]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-wa","showProvinces":false,"scene":"wa","period":"chapter-01","sitePeriods":[],"date":240,"accent":"#596B91","alt":"Scalable map of Daifang, the Korean Strait, secure northern Kyushu stages, and disputed continuations toward Yamatai.","view":{"bounds":[[123.5,29.0],[138.0,40.5]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"political","label":"Recorded center or country","detail":"Squares identify places named or anchored by the continental written record."},{"symbol":"gateway","label":"Maritime stage","detail":"Gateways mark the comparatively secure first stages through Tsushima and Iki."},{"symbol":"route-secure","label":"Comparatively secure itinerary","detail":"The solid indigo route follows stages that can be placed with reasonable confidence."},{"symbol":"route-inferred","label":"Disputed continuation","detail":"Fading dashed branches visualize uncertainty and do not locate Yamatai."},{"symbol":"zone","label":"Candidate field","detail":"Very pale fields represent major hypotheses, never an asserted capital."}],"metadata":{"slug":"1-wa","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Wa in the East Asian field","evidenceFrame":"external written testimony and archaeology"},"id":"map-1-wa","src":"../maps/scenes/1-wa.webp","standing":false,"title":"Wa And The Road To Yamatai","project":"projects/chapter-01/09_wa.qgz","fallback":"../maps/scenes/1-wa.webp","sections":["01.24","01.25","01.26","01.27"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Daifang, the Korean Strait, secure northern Kyushu stages, and disputed continuations","caption":"The route begins with the continental and island stages described in the Chinese account and separates comparatively secure northern Kyushu identifications from the disputed journey beyond them. Competing continuations are shown to make the Yamatai problem spatially intelligible; the map deliberately does not select one location as established.","evidence":"External written testimony and archaeology; the location of Yamatai is not asserted.","sceneTiles":"qgis-scenes/ch01/wa/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/wa/{z}/{x}/{y}.webp","renderBounds":[120.89,26.47,140.61,43.03]},{"type":"interactive","style":"../maps/atlas/qgis-scene-style.json","plate":"1-memory","showProvinces":false,"scene":"memory","period":"chapter-01","sitePeriods":[],"date":275,"accent":"#79596F","alt":"Scalable map distinguishing the traditional Jimmu itinerary from archaeological regional centers at the threshold of Yamato.","view":{"bounds":[[128.5,30.2],[138.0,37.0]],"minZoom":3,"maxZoom":9},"legend":[{"symbol":"route-traditional","label":"Retrospective court itinerary","detail":"The dotted plum route belongs to later tradition and is not a securely dated campaign."},{"symbol":"production","label":"Archaeological concentration","detail":"Hexagons identify caches or material centers independently of the chronicles."},{"symbol":"political","label":"Emerging regional center","detail":"Squares locate broad political landscapes without naming a completed state."},{"symbol":"zone","label":"Converging regional field","detail":"Soft fields emphasize several centers rather than an inevitable national core."}],"metadata":{"slug":"1-memory","plateLabel":"","note":"Scene filters and visual hierarchy are derived from the Chapter 1 prose.","title":"Memory and regional convergence","evidenceFrame":"archaeology distinguished from retrospective tradition"},"id":"map-1-memory","src":"../maps/scenes/1-memory.webp","standing":false,"title":"Memory And Regional Convergence","project":"projects/chapter-01/10_memory.qgz","fallback":"../maps/scenes/1-memory.webp","sections":["01.01","01.28","01.29","01.30","01.31","01.32"],"chapterFeatures":"ch01-features.geojson","localChapterFeatures":"../maps/atlas/ch01-features.geojson","chapterRoutes":"ch01-routes.geojson","localChapterRoutes":"../maps/atlas/ch01-routes.geojson","chapterRegions":"ch01-regions.geojson","localChapterRegions":"../maps/atlas/ch01-regions.geojson","subtitle":"Jimmu's traditional itinerary, Izumo, Kibi, northern Kyushu, Kinki, and the Yamato threshold","caption":"This final field places the traditional Jimmu itinerary beside the independently visible regional centers of northern Kyushu, Izumo, Kibi, Kinki, and early Yamato. Their juxtaposition clarifies how later court memory organized a diverse political landscape, while keeping sacred narrative distinct from archaeological evidence for movement, alliance, and emerging power.","evidence":"Archaeology is kept distinct from retrospective court tradition.","sceneTiles":"qgis-scenes/ch01/memory/{z}/{x}/{y}.webp","localSceneTiles":"../maps/atlas/qgis-scenes/ch01/memory/{z}/{x}/{y}.webp","renderBounds":[126.79,28.704,139.71,38.496]}],"timeline":[{"type":"point","label":"Traditional accession of Jimmu","start":"-660","end":"-660","display_date":"Traditional date: 660 BC","certainty":"traditional","caption":"This is the received court date, not a securely dated archaeological event or contemporary historical report.","id":"event-traditional-accession-of-jimmu"},{"type":"point","label":"Kojiki completed","start":712,"end":712,"display_date":"AD 712","certainty":"secure","caption":"The surviving court narrative was compiled many centuries after the world it retrospectively orders.","id":"event-kojiki-completed"},{"type":"point","label":"Nihon Shoki completed","start":720,"end":720,"display_date":"AD 720","certainty":"secure","caption":"The official chronicle was presented in 720 and constructed a continuous dynastic past.","id":"event-nihon-shoki-completed"},{"type":"point","label":"King of Na in Wa receives a Han seal","start":57,"end":57,"display_date":"AD 57","certainty":"secure","caption":"The Later Han record provides an early fixed point for diplomatic contact with a polity in Wa.","id":"event-king-of-na-in-wa-receives-a-han-seal"},{"type":"point","label":"Wa embassy recorded at the Han court","start":107,"end":107,"display_date":"AD 107","certainty":"secure","caption":"A second Han notice confirms continued diplomacy without implying a unified Japanese state.","id":"event-wa-embassy-recorded-at-the-han-court"},{"type":"span","label":"Himiko's rule in Yamatai","start":180,"end":248,"display_date":"ca. AD 180–248","certainty":"approximate","caption":"The Chinese account places Himiko after civil conflict and before her reported death around 248.","id":"event-himiko-s-rule-in-yamatai"},{"type":"point","label":"Himiko's embassy reaches Wei","start":239,"end":239,"display_date":"AD 239","certainty":"secure","caption":"The embassy supplies the clearest fixed date in the narrative of Yamatai's foreign relations.","id":"event-himiko-s-embassy-reaches-wei"},{"type":"span","label":"Compilation of the Wei account of Wa","start":280,"end":297,"display_date":"ca. AD 280–297","certainty":"approximate","caption":"Chen Shou compiled the Records of the Three Kingdoms after the events it describes, but within the same century.","id":"event-compilation-of-the-wei-account-of-wa"},{"type":"span","label":"Late Pleistocene","start":"-50000","end":"-9700","display_date":"ca. 50,000–9700 BC","certainty":"approximate","caption":"The climatic parent horizon includes the colder landscapes and changing sea levels within which Paleolithic settlement developed.","id":"event-late-pleistocene"},{"type":"span","label":"Upper Paleolithic in Japan","start":"-36000","end":"-14000","display_date":"ca. 36,000–14,000 BC","certainty":"approximate","caption":"A widespread and secure archaeological record is visible by roughly 38,000 years ago; local sequences and end dates vary.","id":"event-upper-paleolithic-in-japan"},{"type":"span","label":"Last Glacial Maximum","start":"-24000","end":"-17000","display_date":"ca. 24,000–17,000 BC","certainty":"approximate","caption":"Peak glacial conditions provide the environmental contrast for later warming, forest expansion, and changing mobility.","id":"event-last-glacial-maximum"},{"type":"span","label":"Incipient Jomon (Mesolithic transition)","start":"-14550","end":"-9350","display_date":"ca. 14,550–9350 BC","certainty":"approximate","caption":"Pottery and changing lifeways overlap the late-glacial transition; the phase is archaeological, not a single archipelago-wide revolution.","id":"event-incipient-jomon-mesolithic-transition"},{"type":"span","label":"Early Holocene","start":"-9700","end":"-5000","display_date":"ca. 9700–5000 BC","certainty":"approximate","caption":"Rapid warming, rising seas, and expanding temperate forests transformed the resource landscape after the Pleistocene.","id":"event-early-holocene"},{"type":"point","label":"Morse excavates the Omori shell mounds","start":1877,"end":1877,"display_date":"AD 1877","certainty":"secure","caption":"Morse's excavation and publication helped establish the cord-marked pottery category later called Jomon.","id":"event-morse-excavates-the-omori-shell-mounds"},{"type":"point","label":"Yamanouchi systematizes the Jomon sequence","start":1937,"end":1937,"display_date":"AD 1937","certainty":"secure","caption":"Yamanouchi Sugao's typological work gave the long Jomon sequence a more systematic chronological structure.","id":"event-yamanouchi-systematizes-the-jomon-sequence"},{"type":"point","label":"Scientific excavation at Iwajuku","start":1949,"end":1949,"display_date":"AD 1949","certainty":"secure","caption":"The excavation established a human occupation beneath the pottery-bearing layers and transformed Japanese Paleolithic archaeology.","id":"event-scientific-excavation-at-iwajuku"},{"type":"span","label":"Initial Jomon","start":"-9350","end":"-5150","display_date":"ca. 9350–5150 BC","certainty":"approximate","caption":"Long regional sequences of pottery, settlement, and subsistence developed after the Incipient phase.","id":"event-initial-jomon"},{"type":"span","label":"Early Jomon","start":"-5150","end":"-3450","display_date":"ca. 5150–3450 BC","certainty":"approximate","caption":"Marine transgression and increasingly substantial settlements frame the Early Jomon in many regions.","id":"event-early-jomon"},{"type":"span","label":"Middle Jomon","start":"-3450","end":"-2450","display_date":"ca. 3450–2450 BC","certainty":"approximate","caption":"Large highland settlements and elaborate material traditions flourished especially in central and eastern Honshu.","id":"event-middle-jomon"},{"type":"span","label":"Late Jomon","start":"-2450","end":"-1250","display_date":"ca. 2450–1250 BC","certainty":"approximate","caption":"Settlement and ritual landscapes shifted after the Middle Jomon florescence, with strong regional variation.","id":"event-late-jomon"},{"type":"span","label":"Final Jomon","start":"-1250","end":"-450","display_date":"ca. 1250–450 BC","certainty":"approximate","caption":"This broad framework is not a uniform end date: farming began earlier in northern Kyushu while Jomon traditions continued elsewhere.","id":"event-final-jomon"},{"type":"span","label":"Initial and Early Yayoi (northern Kyushu)","start":"-900","end":"-400","display_date":"ca. 900–400 BC","certainty":"approximate","caption":"Wet-rice farming began in northern Kyushu in the tenth to ninth centuries BC; the transition reached other regions later.","id":"event-initial-and-early-yayoi-northern-kyushu"},{"type":"span","label":"Middle Yayoi","start":"-400","end":50,"display_date":"ca. 400 BC–AD 50","certainty":"approximate","caption":"Agriculture, continental exchange, metallurgy, and new burial forms expanded unevenly across western and central Japan.","id":"event-middle-yayoi"},{"type":"point","label":"Yayoi-type pottery found at Mukogaoka","start":1884,"end":1884,"display_date":"AD 1884","certainty":"secure","caption":"A pottery vessel found in the Yayoi district eventually lent its name to a distinct archaeological period.","id":"event-yayoi-type-pottery-found-at-mukogaoka"},{"type":"point","label":"Toro settlement discovered","start":1943,"end":1943,"display_date":"AD 1943","certainty":"secure","caption":"Construction exposed the waterlogged remains of a mature rice-farming settlement.","id":"event-toro-settlement-discovered"},{"type":"point","label":"Major excavations begin at Toro","start":1947,"end":1947,"display_date":"AD 1947","certainty":"secure","caption":"Postwar excavation made Toro central to the archaeological definition of Yayoi village life.","id":"event-major-excavations-begin-at-toro"},{"type":"span","label":"Eastern Zhou","start":"-770","end":"-256","display_date":"770–256 BC","certainty":"secure","caption":"The long weakening of Zhou authority forms the earlier continental horizon for intensified mobility and conflict.","id":"event-eastern-zhou"},{"type":"span","label":"Qin empire","start":"-221","end":"-206","display_date":"221–206 BC","certainty":"secure","caption":"Qin unification was brief but transformed the political geography of East Asia.","id":"event-qin-empire"},{"type":"span","label":"Western Han","start":"-202","end":9,"display_date":"202 BC–AD 9","certainty":"secure","caption":"Western Han expansion reorganized continental and peninsular exchange networks.","id":"event-western-han"},{"type":"span","label":"Eastern Han","start":25,"end":220,"display_date":"AD 25–220","certainty":"secure","caption":"Eastern Han sources contain early written notices of Wa and its envoys.","id":"event-eastern-han"},{"type":"span","label":"Lelang Commandery","start":"-108","end":313,"display_date":"108 BC–AD 313","certainty":"secure","caption":"The commandery in northern Korea became a durable node linking Chinese states, peninsular communities, and the archipelago.","id":"event-lelang-commandery"},{"type":"span","label":"Late Yayoi","start":50,"end":250,"display_date":"ca. AD 50–250","certainty":"approximate","caption":"Regional centers, defended settlements, bronze ritual systems, and the polities described in Chinese records belong to this broad horizon.","id":"event-late-yayoi"},{"type":"span","label":"Early Kofun horizon","start":250,"end":350,"display_date":"ca. AD 250–350","certainty":"approximate","caption":"Standardized monumental keyhole tombs spread from the mid-third century and mark a new scale of political integration.","id":"event-early-kofun-horizon"},{"type":"span","label":"Itazuke early paddy horizon","start":"-900","end":"-700","display_date":"ca. ninth–eighth centuries BC","certainty":"approximate","caption":"The earliest farming horizon is placed within northern Kyushu's long Jomon–Yayoi transition; exact site phases remain debated.","id":"event-itazuke-early-paddy-horizon"},{"type":"span","label":"Toro settlement horizon","start":50,"end":200,"display_date":"ca. first–second centuries AD","certainty":"approximate","caption":"Toro belongs within mature eastern Yayoi rice agriculture rather than at the beginning of the northern Kyushu transition.","id":"event-toro-settlement-horizon"},{"type":"point","label":"Wado copper discovery reported","start":708,"end":708,"display_date":"AD 708","certainty":"secure","caption":"The much later copper notice cannot by itself identify the ore sources of Yayoi bronze production.","id":"event-wado-copper-discovery-reported"},{"type":"span","label":"Cao Wei dynasty","start":220,"end":266,"display_date":"AD 220–266","certainty":"secure","caption":"Himiko's diplomacy was conducted with the Wei court during China's Three Kingdoms period.","id":"event-cao-wei-dynasty"},{"type":"point","label":"Reported death of Himiko","start":248,"end":248,"display_date":"ca. AD 248","certainty":"approximate","caption":"The account associates her death with renewed disorder and a large burial mound.","id":"event-reported-death-of-himiko"},{"type":"span","label":"Kojindani bronze deposition horizon","start":"-100","end":100,"display_date":"ca. first century BC–first century AD","certainty":"approximate","caption":"The cache belongs broadly to the Middle–Late Yayoi bronze world; its precise deposition date is not securely fixed.","id":"event-kojindani-bronze-deposition-horizon"},{"type":"span","label":"Traditional reign of Sujin","start":"-97","end":"-30","display_date":"Traditional chronology: 97–30 BC","certainty":"traditional","caption":"The received reign dates are a court chronology and do not securely date the ruler or an associated tomb.","id":"event-traditional-reign-of-sujin"},{"type":"span","label":"Standardized keyhole kofun","start":250,"end":350,"display_date":"ca. AD 250–350","certainty":"approximate","caption":"Large standardized keyhole tombs provide an archaeological horizon for emerging Yamato power in the late third and early fourth centuries.","id":"event-standardized-keyhole-kofun"}],"illustrations":[{"id":"CH01-IMG-001","src":"illustrations/ch01-img001-kanto-paleolithic-camp.webp","alt":"A small mobile group works around a temporary windbreak on a cold river terrace, knapping stone, cooking with heated stones, sorting plants, and repairing a hunting point.","caption":"A mobile Upper Paleolithic camp on a southern Kanto river terrace, reconstructed from archaeological evidence.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-002","src":"illustrations/ch01-img002-kamikuroiwa-hunting-transition.webp","alt":"At a shallow rock shelter, people fit small stone points to light shafts, check a bowstring, and return with small game through a damp warming forest.","caption":"A terminal-Pleistocene hunting camp at Kamikuroiwa, where lighter projectiles accompanied a warming forest.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-003","src":"illustrations/ch01-img003-earliest-pottery-cave.webp","alt":"Near a cave mouth, people form a small round-bottomed vessel from clay coils, add plant fiber, and support another vessel beside a low fire.","caption":"Small, low-fired vessels being formed near Fukui Cave during the transition toward the Jomon period.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-004","src":"illustrations/ch01-img004-earliest-jomon-coast.webp","alt":"A household-sized group gathers shellfish below three small pit dwellings while others tend a hearth beside upright pointed vessels and a dog explores discarded shells.","caption":"An Initial Jomon community above a changing bay, combining shellfish gathering, hearths, pottery, and small pit dwellings.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-005","src":"illustrations/ch01-img005-minabori-village-center.webp","alt":"In light rain, residents repair drainage around a low pit dwelling, open a leaf-lined storage pit, and work around a shared trampled village center.","caption":"Early Jomon households at Minamibori arranged around a shared open center with hearths, drainage, and storage.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-006","src":"illustrations/ch01-img006-torihama-wetland-craft.webp","alt":"On a damp riverbank platform, people carve a wooden bowl, weave a reed basket, apply red lacquer to a comb, and sort gourds, nuts, fish, and cordage.","caption":"Waterlogged remains at Torihama reveal woodworking, basketry, lacquer, fishing, and intensive plant use.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for objects; MODERATE for scene","generated":true,"status":"approved"},{"id":"CH01-IMG-007","src":"illustrations/ch01-img007-yatsugatake-highland-village.webp","alt":"In early autumn, households process chestnuts and acorns around a spring-fed highland village while a family works around the central hearth of a round pit dwelling.","caption":"A Middle Jomon highland community using springs, forest harvests, storage, hearth-centered houses, and obsidian networks.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-008","src":"illustrations/ch01-img008-katsusaka-pottery-workshop.webp","alt":"A highland potter builds a thick Katsusaka jar while a visitor unwraps a smaller mica-tempered vessel and other workers incise clay and tend an open firing bed.","caption":"Middle Jomon potters shaping a Katsusaka vessel as exchanged mica-tempered pottery arrives from another community.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-009","src":"illustrations/ch01-img009-shakado-figurine-breaking.webp","alt":"At a communal work area, an older adult holds a clay figurine while another deliberately breaks one limb and earlier fragments lie sorted nearby.","caption":"The deliberate breaking of a clay figurine at Shakado, reconstructed without assigning a known doctrine or priesthood.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-010","src":"illustrations/ch01-img010-highland-abandonment-rain.webp","alt":"After prolonged rain, residents salvage hearth stones and timbers from a damp house while others carry tools downhill past waterlogged storage pits.","caption":"Repeated wet seasons and failed storage contribute to the gradual contraction of a Jomon highland settlement.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"LOW to MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-011","src":"illustrations/ch01-img011-late-jomon-coastal-season.webp","alt":"A dugout canoe returns with fish while people gather shellfish, mend gear, smoke fish, and repair a bow beside a shallow coast.","caption":"Seasonal Late Jomon coastal work joins canoe travel, fishing, shell gathering, food processing, and hunting.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-012","src":"illustrations/ch01-img012-oyu-stone-circle-gathering.webp","alt":"Small groups arrive at a concentric stone circle carrying salmon and nuts while others adjust stones around a covered shallow pit.","caption":"A communal gathering at the Oyu stone circles, reconstructed from their carefully built Late Jomon landscape.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for layout; MODERATE for activity","generated":true,"status":"approved"},{"id":"CH01-IMG-013","src":"illustrations/ch01-img013-korekawa-lacquer-work.webp","alt":"Craft workers apply red lacquer to a wooden comb and basketry vessel, polish bowls, and inspect a hollow figurine beside a wet working area.","caption":"Final Jomon craftspeople at Korekawa applying red lacquer to wood and basketry with exacting control.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for objects; MODERATE for workshop","generated":true,"status":"approved"},{"id":"CH01-IMG-014","src":"illustrations/ch01-img014-itazuke-early-rice-field.webp","alt":"People work barefoot in a small irrigated paddy beside the Mikasa River while others carry gathered plants, fish, and grain toward a mixed working area.","caption":"Early wet-rice cultivation at Itazuke developed alongside fishing, gathering, stone tools, wooden implements, and older pottery traditions.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for paddy and tools; MODERATE for people and superstructure","generated":true,"status":"approved"},{"id":"CH01-IMG-015","src":"illustrations/ch01-img015-itazuke-jar-burial.webp","alt":"Four adults lower a large joined jar into an angled cemetery pit while a child stands beside smaller jars and other grave forms.","caption":"A joined-jar burial in the cemetery at Itazuke, one of several forms used by the early agricultural community.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for burial forms; MODERATE for ceremony","generated":true,"status":"approved"},{"id":"CH01-IMG-016","src":"illustrations/ch01-img016-doigahama-cemetery-difference.webp","alt":"A burial party prepares an extended east-oriented grave while a central stone cist receives ornaments and simpler graves extend outward.","caption":"Cemetery organization and unequal grave goods at Doigahama make emerging social differences visible.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for grave arrangement; MODERATE for social reading","generated":true,"status":"approved"},{"id":"CH01-IMG-017","src":"illustrations/ch01-img017-yayoi-iron-woodworking.webp","alt":"Craft workers shape granary parts and a wooden rake with a small iron-edged adze while a smith reheats and repairs an edge at a sheltered hearth.","caption":"Scarce iron edges increased precision in Yayoi woodworking long before a large domestic iron industry developed.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-018","src":"illustrations/ch01-img018-toro-irrigation-repair.webp","alt":"Villagers repair a breached paddy bank and wooden sluice while others carry grain toward a raised storehouse and stabilize house posts.","caption":"Villagers at Toro repair irrigation works within a managed landscape of paddies, houses, wells, and raised storage.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + DOCUMENTED RECONSTRUCTION","confidence":"HIGH for site plan; MODERATE for living scene","generated":true,"status":"approved"},{"id":"CH01-IMG-019","src":"illustrations/ch01-img019-defended-plateau-village.webp","alt":"After an alarm, residents move grain toward storage shafts, repair a defensive ditch, extinguish a small fire, and watch the route below.","caption":"Conflict reshaped Yayoi settlement, storage, and collective labor even beyond the moment of battle.","historicalStatus":"ai-reconstruction","evidenceBasis":"ARCHAEOLOGICAL SYNTHESIS","confidence":"MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-020","src":"illustrations/ch01-img020-yasunagata-bronze-casting.webp","alt":"A team aligns stone mold halves, operates bellows, and steadies a small crucible while preparing to cast a bronze bell or weapon form.","caption":"Bronze casting at Yasunagata required heavy molds, alloy control, heat, risk, and coordinated specialist labor.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for molds and debris; MODERATE for furnace arrangement","generated":true,"status":"approved"},{"id":"CH01-IMG-021","src":"illustrations/ch01-img021-sakuragaoka-bronze-burial.webp","alt":"On a wooded ridge, a group lowers bronze bells and ceremonial halberds into an orderly pit while others carry wrapped objects uphill.","caption":"Bronze bells and halberds are deposited on the Sakuragaoka ridge; the purpose of the burial remains uncertain.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for objects; MODERATE for deposition scene","generated":true,"status":"approved"},{"id":"CH01-IMG-022","src":"illustrations/ch01-img022-himiko-secluded-authority.webp","alt":"Himiko sits partly screened with female attendants while a male intermediary receives tribute and relays words to visitors in an outer guarded area.","caption":"A cautious reconstruction of Himiko's secluded authority, female attendants, guards, and male intermediary from the Wei account.","historicalStatus":"ai-reconstruction","evidenceBasis":"CONTEMPORARY TEXTUAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"LOW to MODERATE","generated":true,"status":"approved"},{"id":"CH01-IMG-023","src":"illustrations/ch01-img023-jimmu-court-memory.webp","alt":"A migrating war-band pauses at a mountain pass while the leader later called Jimmu makes a simple offering and scouts study an eastern route.","caption":"Jimmu's eastward expedition is shown as retrospective court memory, not as a securely documented campaign.","historicalStatus":"ai-reconstruction","evidenceBasis":"RETROSPECTIVE TEXTUAL + LITERARY OR MYTHIC + ARCHAEOLOGICAL SYNTHESIS","confidence":"LOW","generated":true,"status":"approved"},{"id":"CH01-IMG-024","src":"illustrations/ch01-img024-kojindani-bronze-deposition.webp","alt":"On a steep slope, coordinated workers place uniform bronze swords in four rows within an oblong pit and prepare bells and spearheads nearby.","caption":"Workers place bronze swords in ordered rows at Kojindani, an extraordinary material concentration in Izumo.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for arrangement; MODERATE for deposition action","generated":true,"status":"approved"},{"id":"CH01-IMG-025","src":"illustrations/ch01-img025-nara-keyhole-mound-emergence.webp","alt":"Teams carry baskets of soil up temporary ramps, compact a terrace, set markers, and coordinate drainage around a developing keyhole-shaped mound.","caption":"A great keyhole mound rising in the Nara basin reveals the new scale of labor at the threshold of the Kofun age.","historicalStatus":"ai-reconstruction","evidenceBasis":"DIRECT MATERIAL + ARCHAEOLOGICAL SYNTHESIS","confidence":"HIGH for mound form and scale; MODERATE for construction scene","generated":true,"status":"approved"}]},"genealogy":{"trees":[{"id":"G1.1","title":"Yamatai Household and Succession Field","caption":"Evidence status: external written testimony. The Chinese account explicitly identifies only the sibling relation between Himiko and her unnamed brother. It does not state that either later ruler was related to Himiko.","nodes":[{"id":"himiko","name":"Himiko","type":"ruler","display_date":"third century AD; death reported about AD 248"},{"id":"himiko_brother","name":"Himiko's unnamed brother","type":"adviser","display_date":"third century AD"},{"id":"male_successor","name":"Unnamed male successor","type":"ruler","display_date":"after Himiko's death"},{"id":"young_female_successor","name":"Thirteen-year-old female successor","type":"ruler","display_date":"after the failed male succession"}],"edges":[{"from":"himiko_brother","to":"himiko","relation":"siblings"},{"from":"himiko_brother","to":"himiko","relation":"adviser-to"},{"from":"male_successor","to":"himiko","relation":"successor-to"},{"from":"young_female_successor","to":"male_successor","relation":"successor-to"}]},{"id":"G1.2","title":"Traditional Sacred Descent of Yamato and Izumo","caption":"Evidence status: retrospective court tradition. This tree records relationships as arranged in the Kojiki and Nihon Shoki. All ancestral and dynastic edges are compressed traditional lines, not immediate parent-child claims unless the relation explicitly says mother-of or siblings. The connections from Amaterasu to Jimmu, from Susa no O to Okuni Nushi, and from Jimmu through Sujin to Jingu abbreviate long received sequences whose intervening figures are omitted. Jingu and Ojin are included only to clarify later attempts to relate Himiko to imperial tradition.","nodes":[{"id":"amaterasu","name":"Amaterasu","type":"deity","display_date":"traditional sacred ancestor of the Yamato line"},{"id":"susa_no_o","name":"Susa no O","type":"deity","display_date":"traditional sibling of Amaterasu"},{"id":"jimmu","name":"Jimmu","type":"ruler","display_date":"traditional first ruler"},{"id":"okuni_nushi","name":"Okuni Nushi","type":"political actor","display_date":"traditional ruler and sacred figure of Izumo"},{"id":"sujin","name":"Sujin","type":"ruler","display_date":"tenth ruler in the received chronology"},{"id":"jingu","name":"Jingu","type":"ruler","display_date":"traditional ruler and mother of Ojin"},{"id":"ojin","name":"Ojin","type":"ruler","display_date":"traditional successor and son of Jingu"}],"edges":[{"from":"amaterasu","to":"susa_no_o","relation":"siblings"},{"from":"amaterasu","to":"jimmu","relation":"traditional-ancestor-of"},{"from":"susa_no_o","to":"okuni_nushi","relation":"traditional-ancestor-of"},{"from":"jimmu","to":"sujin","relation":"received-dynastic-predecessor-of"},{"from":"sujin","to":"jingu","relation":"received-dynastic-predecessor-of"},{"from":"jingu","to":"ojin","relation":"mother-of"}]}]},"sections":[{"id":"01.01","number":"01.01","title":"Court Memory and the Peoples Before Yamato","paragraphs":[{"id":"01.01-p001","text":"The Kojiki and Nihon Shoki begin the human history of the archipelago with a conquest remembered from the viewpoint of the later Yamato court. Kamu-yamato-ihare-biko, later called Jimmu, moves from southern Kyushu toward the Yamato plain with selected clan leaders and meets resistance at every stage. Some opponents submit after their chiefs are killed, while others are represented as physically strange, socially deficient, or scarcely human. The Tsuchigumo, or earth spiders, occupy the lowest place in this hierarchy, and later rulers are credited with completing their destruction.","figures":[{"label":"Map 1a","caption":"The map locates southern Kyushu, Kibi, Yamato, and the regional peoples placed within later court memories of conquest."},{"label":"Map 1b","caption":"The map places Wa, Yamatai, and the emerging Yamato center within the wider archipelago and the continental record."}],"timelineRefs":["event-traditional-accession-of-jimmu","event-kojiki-completed","event-nihon-shoki-completed"],"illustrationRefs":[{"id":"CH01-IMG-023","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.01-p002","text":"These stories are not contemporary reports of a securely dated migration. They are retrospective court traditions that distinguish a divinely favored line from the peoples it claimed the right to command. Their argument is not that the future rulers came first, but that creation, divine counsel, and demonstrated worth entitled them to rule. Even so, the memory of resistance preserves a political truth in altered form. The archipelago was inhabited by many communities before one coalition began the long centralizing process that produced the Yamato kingdom.","figures":[{"label":"Map 1a","caption":"The map locates southern Kyushu, Kibi, Yamato, and the regional peoples placed within later court memories of conquest."},{"label":"Map 1b","caption":"The map places Wa, Yamatai, and the emerging Yamato center within the wider archipelago and the continental record."}],"illustrationRefs":[{"id":"CH01-IMG-023","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.01-p003","text":"The earliest Chinese historians called the inhabitants of the islands Wo, or Wa in Japanese pronunciation, and described numerous organized communities rather than one state. Yamatai appeared among them as the strongest political center known to the continental record. Wa was an external category, perhaps disparaging, while people within the archipelago probably identified themselves through settlements, landscapes, occupations, kin groups, and local polities. Names such as Kumaso, Emishi, Nakatomi, and Imibe belong to different kinds of identity and to different stages in the formation of recorded society.","figures":[{"label":"Map 1a","caption":"The map locates southern Kyushu, Kibi, Yamato, and the regional peoples placed within later court memories of conquest."},{"label":"Map 1b","caption":"The map places Wa, Yamatai, and the emerging Yamato center within the wider archipelago and the continental record."}],"timelineRefs":["event-king-of-na-in-wa-receives-a-han-seal","event-wa-embassy-recorded-at-the-han-court","event-himiko-s-rule-in-yamatai","event-himiko-s-embassy-reaches-wei","event-compilation-of-the-wei-account-of-wa"],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.01-p004","text":"For periods without contemporary writing, these differences must be reconstructed through material remains. Pottery, stone tools, dwellings, skeletons, burial practices, food systems, and settlement patterns reveal changing ways of life, though their archaeological labels were not names used by the people themselves. The broad movement runs from mobile Paleolithic bands, through more settled Jomon communities supported by hunting, fishing, and gathering, to Yayoi societies shaped by rice agriculture, metallurgy, hierarchy, and ritual rule. This was not the unfolding of a nation already present in embryo. It was the long convergence of regional societies.","figures":[{"label":"Map 1a","caption":"The map locates southern Kyushu, Kibi, Yamato, and the regional peoples placed within later court memories of conquest."},{"label":"Map 1b","caption":"The map places Wa, Yamatai, and the emerging Yamato center within the wider archipelago and the continental record."}],"mapRefs":["map-1-islands"],"mapPlacement":"after-paragraph"}]},{"id":"01.02","number":"01.02","title":"Islands at the Continental Margin","paragraphs":[{"id":"01.02-p001","text":"The islands of Japan are the exposed heights of the eastern Asian continental shelf. During colder phases, lower sea levels opened routes across ground later covered by water, while warming near the end of the Pleistocene flooded lowlands and gradually separated the archipelago from surrounding lands. The process did not occur everywhere at once. Passages opened between Kyushu and the Ryukyu chain, between northern Kyushu and the Korean peninsula, and later between Honshu and Hokkaido. The shallow northern route between Hokkaido and Sakhalin remained available longer than the deeper southern crossings.","figures":[{"label":"Map 1a","caption":"The map traces the shelves, straits, plains, and northern and southern corridors through which the archipelago took shape."},{"label":"Map 1b","caption":"The map places the changing island margins within Pleistocene East Asia and the routes followed by animals and people."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-last-glacial-maximum","event-incipient-jomon-mesolithic-transition","event-early-holocene"],"mapRefs":["map-1-islands"],"mapPlacement":"after-paragraph"},{"id":"01.02-p002","text":"The dates and duration of these connections remain open to geological revision, but their historical effect is clear. Southern, western, and northern corridors did not bring the same animals, people, or techniques at the same time. As the sea rose, habitats contracted, migration routes shifted, and water became both boundary and road. The archipelago emerged gradually from a continental margin rather than appearing at one moment as a finished island world.","figures":[{"label":"Map 1a","caption":"The map traces the shelves, straits, plains, and northern and southern corridors through which the archipelago took shape."},{"label":"Map 1b","caption":"The map places the changing island margins within Pleistocene East Asia and the routes followed by animals and people."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-islands"],"mapPlacement":"after-paragraph"},{"id":"01.02-p003","text":"Changing temperatures repeatedly drove animals eastward. Oriental elephants were followed by Naumann elephants, giant deer, and other large mammals entering through western routes, while mammoths moved south from Siberia into Hokkaido but apparently did not reach Honshu. Bones and teeth from the Inland Sea and Lake Nojiri preserve this history beside species that endured, including brown bears and Japanese deer.","figures":[{"label":"Map 1a","caption":"The map traces the shelves, straits, plains, and northern and southern corridors through which the archipelago took shape."},{"label":"Map 1b","caption":"The map places the changing island margins within Pleistocene East Asia and the routes followed by animals and people."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-islands"],"mapPlacement":"after-paragraph"},{"id":"01.02-p004","text":"Most of the archipelago was not glaciated, though cold conditions were severe. Volcanic dust reduced solar warmth, and repeated eruptions spread deep ash over broad regions. In the Kanto plain, deposits from Hakone and Akagi formed the Tama, Shimosueyoshi, Musashino, and Tachikawa loams. These layers created fertile soils, but they also became an unusually clear archive of climate, fauna, and human occupation.","figures":[{"label":"Map 1a","caption":"The map traces the shelves, straits, plains, and northern and southern corridors through which the archipelago took shape."},{"label":"Map 1b","caption":"The map places the changing island margins within Pleistocene East Asia and the routes followed by animals and people."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-last-glacial-maximum","event-incipient-jomon-mesolithic-transition"],"mapRefs":["map-1-islands"],"mapPlacement":"after-paragraph"}]},{"id":"01.03","number":"01.03","title":"Paleolithic Settlement and Movement","paragraphs":[{"id":"01.03-p001","text":"Clear stratification in the southern Kanto plain allows archaeologists to distinguish successive cultural stages beginning about thirty thousand years ago. Claims for substantially earlier occupation, once associated with sites such as Babadan and Zazaragi, require secure geology, unmistakably manufactured artifacts, and reliable dates. The decisive recognition of a Paleolithic presence came at Iwajuku in Gunma Prefecture, where stone artifacts were found beneath the familiar Jomon layers in 1947 and excavated in 1949. Human occupation could no longer be assumed to begin with pottery.","figures":[{"label":"Map 1a","caption":"The map locates Iwajuku, the Kanto plain, obsidian sources, and the principal Paleolithic sites discussed here."},{"label":"Map 1b","caption":"The map shows the western, southern, and northern corridors linking Paleolithic communities to continental Asia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-last-glacial-maximum","event-incipient-jomon-mesolithic-transition","event-early-holocene"],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.03-p002","text":"Thousands of Paleolithic sites have since been identified across the main islands, many of them inland and surprisingly few in caves. The Kanto plain offered a particularly favorable setting. Five major rivers, abundant springs, gravel beds rich in stone, distant mountain shelter, and mixed plant and animal life made repeated year-round occupation possible despite volcanic activity.","figures":[{"label":"Map 1a","caption":"The map locates Iwajuku, the Kanto plain, obsidian sources, and the principal Paleolithic sites discussed here."},{"label":"Map 1b","caption":"The map shows the western, southern, and northern corridors linking Paleolithic communities to continental Asia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-001","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.03-p003","text":"The oldest southern Kanto tools were heavy flakes, choppers, and irregular blades made chiefly from sandstone, slate, and chert. Obsidian and agate were carried from distant sources, sometimes more than one hundred fifty kilometers away. Such movement may reflect hunting expeditions, exchange, or both, but in either case it reveals routes linking scattered bands to valued stone.","figures":[{"label":"Map 1a","caption":"The map locates Iwajuku, the Kanto plain, obsidian sources, and the principal Paleolithic sites discussed here."},{"label":"Map 1b","caption":"The map shows the western, southern, and northern corridors linking Paleolithic communities to continental Asia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-001","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.03-p004","text":"Between about thirty thousand and twenty thousand years ago, the climate reached its coldest level and subalpine forests descended far below their present range. As warming followed, vegetation thickened, oaks expanded, and plant foods became more important while many large animals declined. Sites became larger and more numerous, refined projectile points appeared, and clusters of fire-blackened stones show that heated-stone cooking formed part of camp life.","figures":[{"label":"Map 1a","caption":"The map locates Iwajuku, the Kanto plain, obsidian sources, and the principal Paleolithic sites discussed here."},{"label":"Map 1b","caption":"The map shows the western, southern, and northern corridors linking Paleolithic communities to continental Asia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-last-glacial-maximum","event-incipient-jomon-mesolithic-transition","event-early-holocene"],"illustrationRefs":[{"id":"CH01-IMG-001","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.03-p005","text":"People entered through widely separated corridors. The Korean route probably carried many early arrivals, while southern connections remained open and the far north became habitable only late in the sequence. Human bones attributed to this age are fragmentary and often disputed. The lost Akashi pelvic bone, the remains from Kannon-do and Hijiri-dake, and other finds show how little can be said securely about the appearance of the earliest inhabitants. The stone record is far stronger than the skeletal one.","figures":[{"label":"Map 1a","caption":"The map locates Iwajuku, the Kanto plain, obsidian sources, and the principal Paleolithic sites discussed here."},{"label":"Map 1b","caption":"The map shows the western, southern, and northern corridors linking Paleolithic communities to continental Asia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-001","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"}]},{"id":"01.04","number":"01.04","title":"The Mesolithic Turn","paragraphs":[{"id":"01.04-p001","text":"Around twelve thousand years ago, a brief cooling was followed by rapid warming and a sharp rise in sea level. Subalpine forests retreated, animals moved toward cooler ground, and hunters followed them into uplands, caves, and rock shelters. Large, slow species disappeared, while deer, wild boar, raccoon-dogs, hares, badgers, and other adaptable animals became the main game of later Jomon communities.","figures":[{"label":"Map 1a","caption":"The map locates Kamikuroiwa, Fukui, Sempukuji, Iwashita, and the early pottery and microblade zones."},{"label":"Map 1b","caption":"The map places the Mesolithic transition within the climatic and cultural field extending through Korea, Sakhalin, and Siberia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-incipient-jomon-mesolithic-transition","event-early-holocene"],"illustrationRefs":[{"id":"CH01-IMG-002","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.04-p002","text":"Two innovations changed the terms of survival. The bow and arrow appeared most clearly in northern and central hunting zones, where smaller and faster animals demanded lighter projectiles. Pottery appeared earliest in the south, where difficult subsistence conditions encouraged new ways of boiling plants, storing food, and carrying water. Both developments can be understood as local responses to changing environments, though the wider networks around them remain open to study.","figures":[{"label":"Map 1a","caption":"The map locates Kamikuroiwa, Fukui, Sempukuji, Iwashita, and the early pottery and microblade zones."},{"label":"Map 1b","caption":"The map places the Mesolithic transition within the climatic and cultural field extending through Korea, Sakhalin, and Siberia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-002","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.04-p003","text":"The Kamikuroiwa rock shelter in Shikoku preserves the broadening hunt. Earlier layers contain spearpoints and the bones of deer, boar, bear, and monkey, while later layers add arrowheads and smaller animals such as otters, rabbits, flying squirrels, and birds. The change does not mark one sudden invention but a gradual adjustment of weapons to a new faunal world.","figures":[{"label":"Map 1a","caption":"The map locates Kamikuroiwa, Fukui, Sempukuji, Iwashita, and the early pottery and microblade zones."},{"label":"Map 1b","caption":"The map places the Mesolithic transition within the climatic and cultural field extending through Korea, Sakhalin, and Siberia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-002","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.04-p004","text":"The earliest pottery is associated especially with caves and rock shelters in northwestern Kyushu. Fukui, Sempukuji, and Iwashita yielded small, low-fired vessels with round bases and simple raised or impressed decoration. The extreme radiocarbon dates once assigned to them require calibration and caution, but the south-to-north sequence remains important. At the time these sites were assessed, no securely earlier continental pottery was known, so an indigenous beginning was considered possible rather than proved.","figures":[{"label":"Map 1a","caption":"The map locates Kamikuroiwa, Fukui, Sempukuji, Iwashita, and the early pottery and microblade zones."},{"label":"Map 1b","caption":"The map places the Mesolithic transition within the climatic and cultural field extending through Korea, Sakhalin, and Siberia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-incipient-jomon-mesolithic-transition","event-early-holocene"],"illustrationRefs":[{"id":"CH01-IMG-003","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.04-p005","text":"Pottery enlarged the edible world by making grasses, ferns, roots, and other difficult plants easier to process. It also supported storage and longer residence near nut forests and other seasonal resources. Microblades continued in Kyushu and connected the archipelago with northern Asia, where similar tools ranged through Sakhalin and Siberia. By the end of this transition, older mobile lifeways had not vanished, but the material basis of Jomon settlement had begun to form.","figures":[{"label":"Map 1a","caption":"The map locates Kamikuroiwa, Fukui, Sempukuji, Iwashita, and the early pottery and microblade zones."},{"label":"Map 1b","caption":"The map places the Mesolithic transition within the climatic and cultural field extending through Korea, Sakhalin, and Siberia."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-003","role":"primary"}],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"}]},{"id":"01.05","number":"01.05","title":"Naming Jomon and the First Coastal Communities","paragraphs":[{"id":"01.05-p001","text":"The word Jomon means cord pattern. It arose from Edward Morse's description of pottery excavated at the Omori shell mounds in 1877 and gradually came to name the long period in which such ceramics were made. Yamanouchi Sugao later arranged Jomon pottery into Earliest, Early, Middle, Late, and Latest stages, with an added incipient phase for the pottery that preceded full Jomon lifeways. The sequence remains useful, though regional developments overlap and no stage lasted equally everywhere.","figures":[{"label":"Map 1a","caption":"The map locates Omori, Natsushima, Hanawadai, Hirasaka, and the strong Earliest Jomon concentration in Kanto."},{"label":"Map 1b","caption":"The map shows how rising seas and marine currents reorganized settlement along the eastern coast of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-morse-excavates-the-omori-shell-mounds","event-yamanouchi-systematizes-the-jomon-sequence","event-scientific-excavation-at-iwajuku"],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.05-p002","text":"Jomon is not a perfect equivalent of Neolithic. Early communities used pottery without clear evidence of agriculture, and hunting, fishing, and gathering remained fundamental. The term therefore names a distinctive historical development rather than a single economic definition.","figures":[{"label":"Map 1a","caption":"The map locates Omori, Natsushima, Hanawadai, Hirasaka, and the strong Earliest Jomon concentration in Kanto."},{"label":"Map 1b","caption":"The map shows how rising seas and marine currents reorganized settlement along the eastern coast of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.05-p003","text":"The warm Kuroshio and cooler Oyashio met along eastern Japan, creating rich spawning grounds. Bays, river mouths, tidal pools, and inlets offered shellfish even in winter, while fish supplemented declining terrestrial game. At Natsushima in Kanto, oysters, warm-water clams, freshwater fish, and changing marine species show a shoreline moving inland as the sea rose. Earlier settlements were flooded, and communities withdrew to higher ground.","figures":[{"label":"Map 1a","caption":"The map locates Omori, Natsushima, Hanawadai, Hirasaka, and the strong Earliest Jomon concentration in Kanto."},{"label":"Map 1b","caption":"The map shows how rising seas and marine currents reorganized settlement along the eastern coast of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-incipient-jomon-mesolithic-transition","event-initial-jomon","event-early-jomon","event-middle-jomon"],"illustrationRefs":[{"id":"CH01-IMG-004","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.05-p004","text":"Hanawadai in Ibaraki gives one of the clearest views of a small settlement. Five house pits lay roughly ten meters apart, though probably no more than three were occupied together. The group may have contained only ten or fifteen people. Dogs lived near the houses, outdoor hearths served daily work, and pointed vessels stood upright in the soft soil.","figures":[{"label":"Map 1a","caption":"The map locates Omori, Natsushima, Hanawadai, Hirasaka, and the strong Earliest Jomon concentration in Kanto."},{"label":"Map 1b","caption":"The map shows how rising seas and marine currents reorganized settlement along the eastern coast of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-004","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.05-p005","text":"Human remains convey the cost of survival more sharply than the houses do. A man buried at Hirasaka stood about one hundred sixty-three centimeters tall, but his teeth and bones record severe wear, childhood malnutrition, and early aging. Life expectancy remained low, and regional pottery styles already divided southern, Kanto, and northern communities. Most known sites clustered in Kanto, where rivers, forests, and converging ecological zones supported the largest concentrations of people.","figures":[{"label":"Map 1a","caption":"The map locates Omori, Natsushima, Hanawadai, Hirasaka, and the strong Earliest Jomon concentration in Kanto."},{"label":"Map 1b","caption":"The map shows how rising seas and marine currents reorganized settlement along the eastern coast of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-004","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"}]},{"id":"01.06","number":"01.06","title":"Early Jomon Seas, Villages, and Plant Use","paragraphs":[{"id":"01.06-p001","text":"During the Early Jomon, warming continued and the sea advanced deep into low valleys. Some Kanto settlements that are now far inland once stood near tidal water, while the Inland Sea opened fully and separated Shikoku and Kyushu from Honshu. Shell mounds preserve freshwater and marine clams, oysters, deer, boar, flying squirrels, and other animals, but the middle of the stage brought a striking rise in population.","figures":[{"label":"Map 1a","caption":"The map locates Minabori, Torihama, and the Early Jomon bluff-top and wetland settlements discussed here."},{"label":"Map 1b","caption":"The map places Early Jomon village growth within the warmer coastal and forest environments of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-incipient-jomon-mesolithic-transition","event-initial-jomon","event-early-jomon","event-middle-jomon"],"illustrationRefs":[{"id":"CH01-IMG-005","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.06-p002","text":"Villages occupied bluffs above water and often arranged houses around an open center. Pit dwellings became more substantial, with inner posts, pitched roofs, drainage ditches, and eventually interior hearths. At Minabori in Yokohama, successive houses preserved the same broad arc around a communal space, suggesting that the village plan outlasted individual buildings. Storage pits lined with alternating leaves and nuts protected food and allowed only a small portion to be exposed at one time.","figures":[{"label":"Map 1a","caption":"The map locates Minabori, Torihama, and the Early Jomon bluff-top and wetland settlements discussed here."},{"label":"Map 1b","caption":"The map places Early Jomon village growth within the warmer coastal and forest environments of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-005","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.06-p003","text":"Pottery changed with indoor life. Flat-bottomed vessels stood more securely on hard floors, fiber temper briefly strengthened larger walls, and cord marking gave way in some traditions to incised and impressed lines made with split bamboo. The pot became part of a domestic system of hearth, floor, storage, and repeated residence.","figures":[{"label":"Map 1a","caption":"The map locates Minabori, Torihama, and the Early Jomon bluff-top and wetland settlements discussed here."},{"label":"Map 1b","caption":"The map places Early Jomon village growth within the warmer coastal and forest environments of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-005","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.06-p004","text":"Torihama in Fukui reveals a wider economy than shell and bone alone suggest. Waterlogged deposits preserved gourds, possible beans, ropes, baskets, oars, boards, adzes, bows, bowls, a comb, and some of the oldest lacquered objects known from the archipelago. The site also contained walnuts, hazelnuts, acorns, fish, shellfish, and many hunted mammals. Gourds and beans may indicate cultivation or deliberate tending, but the degree of management remains disputed.","figures":[{"label":"Map 1a","caption":"The map locates Minabori, Torihama, and the Early Jomon bluff-top and wetland settlements discussed here."},{"label":"Map 1b","caption":"The map places Early Jomon village growth within the warmer coastal and forest environments of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-006","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"},{"id":"01.06-p005","text":"Whatever the status of those plants, Torihama shows that Early Jomon life was neither simple nor uniform. Woodworking, basketry, lacquer, fishing, hunting, gathering, storage, and perhaps limited cultivation formed one interdependent economy. The settlement world was becoming more durable without ceasing to depend on many landscapes at once.","figures":[{"label":"Map 1a","caption":"The map locates Minabori, Torihama, and the Early Jomon bluff-top and wetland settlements discussed here."},{"label":"Map 1b","caption":"The map places Early Jomon village growth within the warmer coastal and forest environments of the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-006","role":"primary"}],"mapRefs":["map-1-jomon-coasts"],"mapPlacement":"after-paragraph"}]},{"id":"01.07","number":"01.07","title":"The Middle Jomon Highlands","paragraphs":[{"id":"01.07-p001","text":"Around 3500 BC, large settlements flourished in the central mountains, especially around the Yatsugatake and Shinshu regions. The climate remained warm, but altitude offered cooler summers, abundant springs, mixed forests, game, and access to obsidian. Nagano alone contained thousands of Middle Jomon sites, many between eight hundred and twelve hundred meters above sea level.","figures":[{"label":"Map 1a","caption":"The map locates Yatsugatake, Lake Suwa, Idojiri, and the dense Middle Jomon settlement belt of Chubu and Kanto."},{"label":"Map 1b","caption":"The map shows the highland zone within wider routes connecting forests, obsidian sources, coasts, and lowland communities."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-early-jomon","event-middle-jomon","event-late-jomon"],"illustrationRefs":[{"id":"CH01-IMG-007","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.07-p002","text":"The economy rested on several overlapping harvests. Horse chestnuts came first, followed by chestnuts, acorns, and walnuts, while yams, lily bulbs, bracken, arrowroot, mushrooms, and other plants broadened the diet. Bitter acorns and horse chestnuts required prolonged leaching, which helps explain the importance of springs. Charred breadlike remains from Idojiri suggest that starches were processed, steamed, and stored for winter. Whether this amounted to agriculture remains debated, but long residence almost certainly encouraged selection, transplanting, and management of useful plants.","figures":[{"label":"Map 1a","caption":"The map locates Yatsugatake, Lake Suwa, Idojiri, and the dense Middle Jomon settlement belt of Chubu and Kanto."},{"label":"Map 1b","caption":"The map shows the highland zone within wider routes connecting forests, obsidian sources, coasts, and lowland communities."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-007","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.07-p003","text":"Middle Jomon houses were usually round, about six meters across, with deep floors, heavy posts, and a hearth near the center. The hearth gave warmth and light and became the fixed point around which domestic life was repeatedly rebuilt. Villages contained many overlapping houses, but pottery sequences suggest that only a fraction were occupied at one time. A typical dwelling may have held about five people.","figures":[{"label":"Map 1a","caption":"The map locates Yatsugatake, Lake Suwa, Idojiri, and the dense Middle Jomon settlement belt of Chubu and Kanto."},{"label":"Map 1b","caption":"The map shows the highland zone within wider routes connecting forests, obsidian sources, coasts, and lowland communities."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-007","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.07-p004","text":"Rebuilding was not always forced by decay. At Yosukeone in Nagano, hearth stones and ritual objects were moved from older houses into new ones only a few meters away. Illness, death, poor harvests, or perceived pollution may have made a dwelling unfit while leaving the site itself desirable. The village endured by relocating its center within a familiar landscape.","figures":[{"label":"Map 1a","caption":"The map locates Yatsugatake, Lake Suwa, Idojiri, and the dense Middle Jomon settlement belt of Chubu and Kanto."},{"label":"Map 1b","caption":"The map shows the highland zone within wider routes connecting forests, obsidian sources, coasts, and lowland communities."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-007","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.07-p005","text":"The population of the archipelago reached its Jomon maximum during this stage, with the greatest density in Kanto and Chubu. The florescence was powerful but geographically narrow. It depended on a central belt where altitude, springs, forest harvests, obsidian routes, and access to lower country could be joined in one seasonal system.","figures":[{"label":"Map 1a","caption":"The map locates Yatsugatake, Lake Suwa, Idojiri, and the dense Middle Jomon settlement belt of Chubu and Kanto."},{"label":"Map 1b","caption":"The map shows the highland zone within wider routes connecting forests, obsidian sources, coasts, and lowland communities."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-007","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"}]},{"id":"01.08","number":"01.08","title":"Pottery, Exchange, and Ritual in the Highlands","paragraphs":[{"id":"01.08-p001","text":"Middle Jomon pottery grew larger and more varied. Upright jars, bowls, steamers, cups, lamps, and ritual vessels appeared beside one another, while mountain potters built thick walls with modeled ridges, handles, and dramatic rims. Katsusaka wares flourished in the highlands, Otamadai pottery in the lowlands and coastal plain, and later Kasori E vessels favored dense oblique cord marking.","figures":[{"label":"Map 1a","caption":"The map locates Katsusaka, Otamadai, Hiraide, Shakado, and other centers of Middle Jomon pottery and ritual."},{"label":"Map 1b","caption":"The map shows the relations joining mountain workshops, lowland settlements, and long-distance exchange routes."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-early-jomon","event-middle-jomon","event-late-jomon"],"illustrationRefs":[{"id":"CH01-IMG-008","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.08-p002","text":"Otamadai clay was tempered with phlogopite mica, which glittered, resisted heat, and reduced contraction. Because mica sources were limited, the wide distribution of these vessels implies movement of clay, pots, or potters. Katsusaka settlements stood near springs and the routes leading toward obsidian sources south of Lake Suwa. Pottery, stone, and architectural practice linked mountain and plain rather than enclosing them in separate worlds.","figures":[{"label":"Map 1a","caption":"The map locates Katsusaka, Otamadai, Hiraide, Shakado, and other centers of Middle Jomon pottery and ritual."},{"label":"Map 1b","caption":"The map shows the relations joining mountain workshops, lowland settlements, and long-distance exchange routes."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-008","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.08-p003","text":"Snakes and animal-like heads often appear on Katsusaka rims. The venomous mamushi, with its hibernation, shedding skin, and dangerous bite, may have supported associations with death and renewal. Clay figurines became far more numerous, many emphasizing breasts and hips, and a few bearing coiled snakes. Birth, fertility, healing, and female ritual authority are plausible interpretations, but no single recovered doctrine explains every image.","figures":[{"label":"Map 1a","caption":"The map locates Katsusaka, Otamadai, Hiraide, Shakado, and other centers of Middle Jomon pottery and ritual."},{"label":"Map 1b","caption":"The map shows the relations joining mountain workshops, lowland settlements, and long-distance exchange routes."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-009","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.08-p004","text":"Context gives firmer evidence than symbolism alone. At Hiraide, one burned house stood apart and held most of the site's figurines, perhaps after a ceremony connected with childbirth or pollution. At Shakado, more than a thousand figurines were found in fragments, suggesting deliberate breaking. Stone phalli, lamps, and unusual vessels sometimes occur with them, while one house at Idojiri gathered nearly every major ritual object of the period.","figures":[{"label":"Map 1a","caption":"The map locates Katsusaka, Otamadai, Hiraide, Shakado, and other centers of Middle Jomon pottery and ritual."},{"label":"Map 1b","caption":"The map shows the relations joining mountain workshops, lowland settlements, and long-distance exchange routes."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-009","role":"primary"}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.08-p005","text":"Later Middle Jomon practices turned more visibly toward the dead. Large pots were placed beneath entrances or inverted over infant remains, sometimes after their bases had been removed or pierced. Adults may have been deposited in abandoned postholes or houses at the edge of a settlement. Former dwellings accumulated broken pottery and tools, becoming places where domestic debris, memory, and ritual disposal met.","figures":[{"label":"Map 1a","caption":"The map locates Katsusaka, Otamadai, Hiraide, Shakado, and other centers of Middle Jomon pottery and ritual."},{"label":"Map 1b","caption":"The map shows the relations joining mountain workshops, lowland settlements, and long-distance exchange routes."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"},{"id":"01.08-p006","text":"The bodies themselves record the labor of this world. Heavy digging, grinding, building, and food preparation shaped bones and teeth, while high carbohydrate consumption left a clear dental signature. Earlier attempts to assign particular skeletal changes rigidly to male or female work require caution. What remains unmistakable is the physical cost of maintaining a settled highland economy.","figures":[{"label":"Map 1a","caption":"The map locates Katsusaka, Otamadai, Hiraide, Shakado, and other centers of Middle Jomon pottery and ritual."},{"label":"Map 1b","caption":"The map shows the relations joining mountain workshops, lowland settlements, and long-distance exchange routes."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-jomon-highlands"],"mapPlacement":"after-paragraph"}]},{"id":"01.09","number":"01.09","title":"The End of the Highland World","paragraphs":[{"id":"01.09-p001","text":"Around 2400 BC, repeated rains appear to have damaged the nut harvests on which the highland settlements depended. Communities left many mountain sites and moved toward lower river valleys and the coast, where marine foods offered a different security. In Chubu, the recorded number of settlements fell from nearly three thousand in the Middle Jomon to fewer than one thousand in the Late stage and about two hundred fifty in the Latest.","figures":[{"label":"Map 1a","caption":"The map shows the contraction of the Chubu highlands and the movement of settlement toward valleys, coasts, and other regions."},{"label":"Map 1b","caption":"The map places the end of the highland florescence within broader climatic change across the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-early-jomon","event-middle-jomon","event-late-jomon"],"illustrationRefs":[{"id":"CH01-IMG-010","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.09-p002","text":"The system did not fail because it had been primitive. It failed because a successful, densely settled way of life had become closely bound to a vulnerable forest economy. When the harvests changed, the geography of settlement changed with them.","figures":[{"label":"Map 1a","caption":"The map shows the contraction of the Chubu highlands and the movement of settlement toward valleys, coasts, and other regions."},{"label":"Map 1b","caption":"The map places the end of the highland florescence within broader climatic change across the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-010","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.09-p003","text":"Movement redistributed people across the archipelago. Regions that had held few Middle Jomon settlements, including parts of the Kinki, Chugoku, Shikoku, Kyushu, and the north, received larger populations. Kasori E pottery spread farther than earlier highland styles, and erased cord marking became widely shared. Migration weakened some regional boundaries while creating new combinations of local practice.","figures":[{"label":"Map 1a","caption":"The map shows the contraction of the Chubu highlands and the movement of settlement toward valleys, coasts, and other regions."},{"label":"Map 1b","caption":"The map places the end of the highland florescence within broader climatic change across the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-middle-jomon","event-late-jomon","event-final-jomon"],"illustrationRefs":[{"id":"CH01-IMG-010","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"}]},{"id":"01.10","number":"01.10","title":"Late Jomon Coasts and Seasonal Life","paragraphs":[{"id":"01.10-p001","text":"Many Late Jomon communities occupied sheltered bays, river mouths, and coastal terraces. Their refuse formed immense shell mounds, some more than one hundred meters long, from Hokkaido and northern Honshu to Kanto, the Inland Sea, Kyushu, and islands farther south. The rugged Japan Sea coast preserves far fewer.","figures":[{"label":"Map 1a","caption":"The map locates major Late Jomon shell-mound regions, river mouths, bays, and canoe routes."},{"label":"Map 1b","caption":"The map shows how coastal communities participated in seasonal marine networks from Hokkaido to Kyushu."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-middle-jomon","event-late-jomon","event-final-jomon"],"illustrationRefs":[{"id":"CH01-IMG-011","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.10-p002","text":"Shell growth rings suggest that clamming was concentrated in spring, with a smaller season in late summer. Fishing expanded from inshore waters to tuna, bonito, salmon, trout, and porpoises according to region. Dugout canoes carried crews into deeper water, while hunting remained important for deer and boar. The year followed a broad rhythm of shellfish in spring, fishing in summer, nuts in autumn, and hunting in winter.","figures":[{"label":"Map 1a","caption":"The map locates major Late Jomon shell-mound regions, river mouths, bays, and canoe routes."},{"label":"Map 1b","caption":"The map shows how coastal communities participated in seasonal marine networks from Hokkaido to Kyushu."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-011","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.10-p003","text":"Houses were often shallow and are difficult to trace. Some Kanto settlements included stone-paved floors or open paved spaces containing phallic stones and unusual vessels. These have been interpreted as houses of ritual leaders or communal ceremonial places, but their plans do not determine the answer.","figures":[{"label":"Map 1a","caption":"The map locates major Late Jomon shell-mound regions, river mouths, bays, and canoe routes."},{"label":"Map 1b","caption":"The map shows how coastal communities participated in seasonal marine networks from Hokkaido to Kyushu."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-011","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.10-p004","text":"The heavy chipped axes of the Middle Jomon almost disappeared, while smaller ground and polished tools became more common. Small arrowheads were used with simple bows, and some may have been tipped with aconite poison, though direct proof is limited. Pottery became thinner and more controlled, with restrained linear decoration that followed the vessel's shape. In Kyushu, dark polished Goryo wares departed sharply from cord-marked traditions and may reflect distant continental connections. Mat impressions reveal developed basketry, while softened mulberry bark and woven plant fiber probably provided clothing and rainwear.","figures":[{"label":"Map 1a","caption":"The map locates major Late Jomon shell-mound regions, river mouths, bays, and canoe routes."},{"label":"Map 1b","caption":"The map shows how coastal communities participated in seasonal marine networks from Hokkaido to Kyushu."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-011","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"}]},{"id":"01.11","number":"01.11","title":"Communal Ritual and the Dead","paragraphs":[{"id":"01.11-p001","text":"Open spaces between houses acquired greater ceremonial weight. At Kainohana in Chiba, a long-lived settlement produced stone phalli, stone swords, clay disks, plaques, and figurines, many of them concentrated in a shared central area. Two houses contained smaller groups of the same objects and may have belonged to ritual specialists, though no office can be recovered from the remains. The later, smaller community used the common space more intensively, showing that population decline did not entail ritual decline.","figures":[{"label":"Map 1a","caption":"The map locates Kainohana, Oyu, Tsugumo, Yoshigo, and other sites of communal ritual and burial."},{"label":"Map 1b","caption":"The map places stone circles, cemeteries, salt, asphalt, and craft exchange within the wider Late Jomon world."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-middle-jomon","event-late-jomon","event-final-jomon"],"illustrationRefs":[{"id":"CH01-IMG-009","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.11-p002","text":"Figurines became common at large shell mounds and often bore more explicitly human features than the highland forms. Northern examples sometimes show squatting bodies, which have been connected with childbirth, flexed burial, healing, or sympathetic magic. Their exact meanings remain uncertain, but repeated handling, breaking, and deposition show that they belonged to enduring domestic and communal practices.","figures":[{"label":"Map 1a","caption":"The map locates Kainohana, Oyu, Tsugumo, Yoshigo, and other sites of communal ritual and burial."},{"label":"Map 1b","caption":"The map places stone circles, cemeteries, salt, asphalt, and craft exchange within the wider Late Jomon world."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-009","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.11-p003","text":"Burials increasingly occupied reserved areas. Many bodies were flexed, some were coated with red ochre, and ornaments such as shell bracelets and clay earrings occurred especially with women. Ochre may have signified blood, preservation, or rebirth, while flexion may reflect wrapping or a return to an enclosed state. The procedures are visible; their spoken meanings are not.","figures":[{"label":"Map 1a","caption":"The map locates Kainohana, Oyu, Tsugumo, Yoshigo, and other sites of communal ritual and burial."},{"label":"Map 1b","caption":"The map places stone circles, cemeteries, salt, asphalt, and craft exchange within the wider Late Jomon world."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.11-p004","text":"Some communities removed or filed teeth during adolescence. The practice varied by settlement, sex, and individual, and was especially prominent in the southern Tokai region. It may have marked initiation, marriage, lineage, or movement between groups. Whatever the rule, the body had become a durable surface on which affiliation could be made visible.","figures":[{"label":"Map 1a","caption":"The map locates Kainohana, Oyu, Tsugumo, Yoshigo, and other sites of communal ritual and burial."},{"label":"Map 1b","caption":"The map places stone circles, cemeteries, salt, asphalt, and craft exchange within the wider Late Jomon world."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.11-p005","text":"Northern communities also built stone circles and alignments. At Oyu in Akita, thousands of stones form two great pairs of concentric rings with smaller radial settings inside them. The circles may have joined seasonal salmon gatherings, burial, exchange, and ceremony. Ordinary houses are scarce nearby, making their separation from daily residence more secure than any proposed calendar.","figures":[{"label":"Map 1a","caption":"The map locates Kainohana, Oyu, Tsugumo, Yoshigo, and other sites of communal ritual and burial."},{"label":"Map 1b","caption":"The map places stone circles, cemeteries, salt, asphalt, and craft exchange within the wider Late Jomon world."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-middle-jomon","event-late-jomon","event-final-jomon"],"illustrationRefs":[{"id":"CH01-IMG-012","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.11-p006","text":"Craft and exchange likewise became more visible. Some settlements held more fishhooks, stone tools, or unfinished objects than their inhabitants appear to have needed. Coastal communities exchanged salt, dried fish, shell products, and seaweed for obsidian, bone, horn, and inland foods, while asphalt from a few Akita sources traveled widely through Tohoku. These routes joined communities without requiring permanent markets or professional merchants.","figures":[{"label":"Map 1a","caption":"The map locates Kainohana, Oyu, Tsugumo, Yoshigo, and other sites of communal ritual and burial."},{"label":"Map 1b","caption":"The map places stone circles, cemeteries, salt, asphalt, and craft exchange within the wider Late Jomon world."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-012","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"}]},{"id":"01.12","number":"01.12","title":"Northern Latest Jomon and Lacquer","paragraphs":[{"id":"01.12-p001","text":"In a widely used calibrated chronology, the Final (or Latest) Jomon spans roughly 1250 to 450 BC, though its regional boundaries vary sharply—most of all in northern Kyushu, where wet-rice cultivation had begun by the tenth to ninth centuries BC. Settlement contracted sharply across the archipelago, and more than half of known sites lay in Tohoku. Northern communities continued to draw on horse chestnuts, walnuts, deer, salmon, and other marine foods, sometimes while managing useful plants and disturbing nearby forests.","figures":[{"label":"Map 1a","caption":"The map locates the northern Kamegaoka cultural field and the wet sites that preserved lacquer and household goods."},{"label":"Map 1b","caption":"The map shows the northern concentration of Latest Jomon settlement within the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-jomon","event-final-jomon","event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi"],"illustrationRefs":[{"id":"CH01-IMG-013","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.12-p002","text":"House plans are often elusive. In parts of the Kamegaoka cultural field, dwellings may have stood above the ground on forked posts rather than in deep pits. Wet sites preserve a richer domestic world of bowls, cups, baskets, combs, and ritual objects. Small vessels were polished, burnished, or lacquered, and household members may have possessed individual cups or bowls.","figures":[{"label":"Map 1a","caption":"The map locates the northern Kamegaoka cultural field and the wet sites that preserved lacquer and household goods."},{"label":"Map 1b","caption":"The map shows the northern concentration of Latest Jomon settlement within the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-013","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.12-p003","text":"Lacquer had become a specialized craft. Applied over red pigment to wood and pottery, it protected surfaces and created a valued finish, as seen in combs, baskets, and a ceremonial sword. Hollow figurines, including the famous goggle-eyed forms, also belong to this vigorous northern ritual world. Their identities are uncertain, but their technical assurance is not.","figures":[{"label":"Map 1a","caption":"The map locates the northern Kamegaoka cultural field and the wet sites that preserved lacquer and household goods."},{"label":"Map 1b","caption":"The map shows the northern concentration of Latest Jomon settlement within the archipelago."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-013","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"}]},{"id":"01.13","number":"01.13","title":"Rice at the End of Jomon","paragraphs":[{"id":"01.13-p001","text":"Kyushu's population rose after the Late Jomon migrations, placing greater pressure on local resources while proximity to the continent opened new possibilities. Rice impressions have been reported on Latest Jomon pottery, especially in northern Kyushu, and rice pollen appears with weeds associated with forest clearance. At Itazuke, a paddy surface linked to Yusu pottery preserved the footprints of adults and a child working in wet ground. The discovery made a clean boundary between Jomon and Yayoi impossible.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke and other northern Kyushu sites where rice and mixed cultivation appear before the end of Jomon."},{"label":"Map 1b","caption":"The map places northern Kyushu within maritime routes to Korea, eastern China, and the Ryukyu Islands."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-jomon","event-final-jomon","event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi"],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.13-p002","text":"Rice was not the only crop under consideration. Millet, barley, wheat, and beans have been identified in late Jomon or early transitional contexts, though some identifications and dates remain debated. The essential change was not the sudden arrival of one grain, but the growth of a mixed productive economy in which managed plants, dry fields, and wet paddies joined older fishing, hunting, and gathering.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke and other northern Kyushu sites where rice and mixed cultivation appear before the end of Jomon."},{"label":"Map 1b","caption":"The map places northern Kyushu within maritime routes to Korea, eastern China, and the Ryukyu Islands."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.13-p003","text":"The relation between Jomon populations and later Ainu was once treated too simply. Northern Latest Jomon communities contributed to the ancestry and culture of later northern peoples, but Jomon society across the archipelago was never one homogeneous population. Skeletal studies show both continuity and regional difference, while the historical labels Emishi and Ezo belong to later political encounters. No single line can turn the entire Jomon world into one later people.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke and other northern Kyushu sites where rice and mixed cultivation appear before the end of Jomon."},{"label":"Map 1b","caption":"The map places northern Kyushu within maritime routes to Korea, eastern China, and the Ryukyu Islands."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.13-p004","text":"By the end of the period, the archipelago contained declining northern and eastern concentrations, expanding communities in Kyushu, and new forms of food production along the maritime approaches to Korea and China. The transition to Yayoi was therefore regional, cumulative, and uneven.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke and other northern Kyushu sites where rice and mixed cultivation appear before the end of Jomon."},{"label":"Map 1b","caption":"The map places northern Kyushu within maritime routes to Korea, eastern China, and the Ryukyu Islands."},{"label":"Map 1.1","caption":"The source map surveys Paleolithic and Jomon sites across the archipelago; its OCR labels remain provisional because the image was not visually checked."}],"timelineRefs":["event-late-jomon","event-final-jomon","event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi"],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"}]},{"id":"01.14","number":"01.14","title":"The Yayoi Transition","paragraphs":[{"id":"01.14-p001","text":"The name Yayoi comes from a district near the University of Tokyo where pottery unlike Jomon wares was found in the late nineteenth century. Its significance remained uncertain for decades, and the period acquired a clear archaeological identity only through later excavation, especially at Toro. Yayoi roughly overlaps the Han dynasties of China, but it began earlier and ended later than that continental frame.","figures":[{"label":"Map 1a","caption":"The map locates Yayoi, Toro, northern Kyushu, and the Inland Sea route followed by early Yayoi expansion."},{"label":"Map 1b","caption":"The map places the Yayoi transition within Han China, the Korean peninsula, Lelang, and the maritime approaches to the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-yayoi-type-pottery-found-at-mukogaoka","event-toro-settlement-discovered","event-major-excavations-begin-at-toro"],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.14-p002","text":"Older explanations opposed foreign invasion to indigenous development. Neither is sufficient. Rice agriculture, metallurgy, and associated tools entered through northern Kyushu over several centuries. They came from the Korean peninsula and eastern China, but existing communities adopted them rather than receiving them through one conquest. The small population of Latest Jomon Kyushu made immigration important, yet no archaeological evidence supports total replacement.","figures":[{"label":"Map 1a","caption":"The map locates Yayoi, Toro, northern Kyushu, and the Inland Sea route followed by early Yayoi expansion."},{"label":"Map 1b","caption":"The map places the Yayoi transition within Han China, the Korean peninsula, Lelang, and the maritime approaches to the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.14-p003","text":"Romantic claims that Xu Fu brought rice and metal in a single expedition fail against the different chronologies of those technologies. The opposite claim that southern Jomon communities independently domesticated rice and invented bronze and iron ignores the continental origins of the plants and techniques. The transition was neither an isolated invention nor a complete transplantation. It was a long process of migration, teaching, exchange, and local recombination.","figures":[{"label":"Map 1a","caption":"The map locates Yayoi, Toro, northern Kyushu, and the Inland Sea route followed by early Yayoi expansion."},{"label":"Map 1b","caption":"The map places the Yayoi transition within Han China, the Korean peninsula, Lelang, and the maritime approaches to the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.14-p004","text":"Political upheaval on the continent accelerated movement. The collapse of Zhou authority, the unification of Qin, the expansion of Han, and the creation of the Lelang commandery in northern Korea altered the routes through which people and objects reached the archipelago. Maritime travel from Korea through Tsushima and Iki connected northern Kyushu to a broader East Asian field of trade and diplomacy.","figures":[{"label":"Map 1a","caption":"The map locates Yayoi, Toro, northern Kyushu, and the Inland Sea route followed by early Yayoi expansion."},{"label":"Map 1b","caption":"The map places the Yayoi transition within Han China, the Korean peninsula, Lelang, and the maritime approaches to the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-eastern-zhou","event-qin-empire","event-western-han","event-eastern-han","event-lelang-commandery"],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.14-p005","text":"Pottery, mirrors, weapons, and Korean-style stone objects help date the expansion. Ongagawa wares spread from northern Kyushu along the Inland Sea to the Kinki and Tokai, while Yusu pottery remains difficult to separate from the earliest Yayoi forms. As rice cultivation moved east and north, local Jomon traditions persisted, especially beyond the dense forests of the Tokai and in northern Honshu.","figures":[{"label":"Map 1a","caption":"The map locates Yayoi, Toro, northern Kyushu, and the Inland Sea route followed by early Yayoi expansion."},{"label":"Map 1b","caption":"The map places the Yayoi transition within Han China, the Korean peninsula, Lelang, and the maritime approaches to the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"}]},{"id":"01.15","number":"01.15","title":"Rice, Mixed Subsistence, and Settlement Expansion","paragraphs":[{"id":"01.15-p001","text":"Yayoi communities did not seek entirely new landscapes. Large sites in Chiba and Nagano contain both Jomon and Yayoi houses, showing that old settlements could be reoccupied or transformed as economic priorities changed. Burial practices also crossed the conventional boundary, with jars and circular pits continuing in eastern regions before square-moated graves became common.","figures":[{"label":"Map 1a","caption":"The map shows the spread of rice fields, wells, mixed farming, and reused settlements from Kyushu toward eastern Honshu."},{"label":"Map 1b","caption":"The map places local agricultural change within the wider movement of crops and techniques from continental East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.15-p002","text":"The earliest rice suited a temperate zone extending from the lower Yangtze region toward southern Korea. Short-grained rice could be dried, toasted, and stored compactly, but it demanded protection from damp, insects, and rodents. Later communities raised storehouses above the ground and used wooden pounders to prepare grain and fertilizing material.","figures":[{"label":"Map 1a","caption":"The map shows the spread of rice fields, wells, mixed farming, and reused settlements from Kyushu toward eastern Honshu."},{"label":"Map 1b","caption":"The map places local agricultural change within the wider movement of crops and techniques from continental East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.15-p003","text":"Wet paddies eventually became the hallmark of Yayoi agriculture, but early production also included marsh planting and dry fields. Shell mounds, animal bones, fish, and wild plants remain common at early farming sites. Rice therefore entered a mixed economy rather than abolishing older subsistence in one generation.","figures":[{"label":"Map 1a","caption":"The map shows the spread of rice fields, wells, mixed farming, and reused settlements from Kyushu toward eastern Honshu."},{"label":"Map 1b","caption":"The map places local agricultural change within the wider movement of crops and techniques from continental East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.15-p004","text":"The spread of cultivation changed vegetation. Pollen from some sites shows declining oak and chinkapin, increasing rice and water plants, and the multiplication of pine after clearance. The village landscape was made rather than merely occupied. Fields, paths, ditches, wells, and storage altered the relation between households and the land on which they depended.","figures":[{"label":"Map 1a","caption":"The map shows the spread of rice fields, wells, mixed farming, and reused settlements from Kyushu toward eastern Honshu."},{"label":"Map 1b","caption":"The map places local agricultural change within the wider movement of crops and techniques from continental East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"}]},{"id":"01.16","number":"01.16","title":"Itazuke and the First Agricultural Communities","paragraphs":[{"id":"01.16-p001","text":"Itazuke lay beside the Mikasa River in northern Kyushu and was occupied in the Earliest Jomon, the Latest Jomon, and again during Early and Middle Yayoi. Its threshold character appears in pottery that is difficult to classify cleanly, beside unmistakable Yayoi storage jars, wooden field stakes, and a long ditch that may have carried water or defended the settlement.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke beside the Mikasa River and distinguishes its fields, ditch, working area, and cemetery."},{"label":"Map 1b","caption":"The map places Itazuke within the northern Kyushu network of early farming communities and Korean-strait exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-final-jomon","event-initial-and-early-yayoi-northern-kyushu","event-itazuke-early-paddy-horizon","event-middle-yayoi"],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.16-p002","text":"Wooden rakes and hoes worked the fields. Stone reaping knives, polished axes, and spindle whorls belonged to the new economy, while iron tools must have shaped much of the wood even though no iron scraps were found in the earliest levels. The absence of house pits may mean that dwellings stood on the surface, where damp ground made sunken floors uncomfortable.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke beside the Mikasa River and distinguishes its fields, ditch, working area, and cemetery."},{"label":"Map 1b","caption":"The map places Itazuke within the northern Kyushu network of early farming communities and Korean-strait exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-014","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.16-p003","text":"North of the working area lay a cemetery about forty by sixty meters across. It contained sixty-three jar burials and fifty rectangular pits, at least twelve of which probably held wooden coffins. Children were usually placed in single jars, while adults could be enclosed in two joined vessels. The dead occupied a defined space apart from fields and storage.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke beside the Mikasa River and distinguishes its fields, ditch, working area, and cemetery."},{"label":"Map 1b","caption":"The map places Itazuke within the northern Kyushu network of early farming communities and Korean-strait exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-015","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.16-p004","text":"Jar burial changed through time. Vessels first lay horizontally, then at an angle, and finally upright with their mouths downward, partly to resist the weight of the earth. The practice became extremely common in Middle Yayoi northern Kyushu, with some cemeteries containing hundreds or even thousands of jars. By Late Yayoi, simpler pits for bodies wrapped in mats became more usual.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke beside the Mikasa River and distinguishes its fields, ditch, working area, and cemetery."},{"label":"Map 1b","caption":"The map places Itazuke within the northern Kyushu network of early farming communities and Korean-strait exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-015","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.16-p005","text":"The cemetery belonged to an agricultural community, but it also records the first visible ordering of age, household, and perhaps status. The fields fed the settlement; the burial ground gave its members a durable place within it.","figures":[{"label":"Map 1a","caption":"The map locates Itazuke beside the Mikasa River and distinguishes its fields, ditch, working area, and cemetery."},{"label":"Map 1b","caption":"The map places Itazuke within the northern Kyushu network of early farming communities and Korean-strait exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-015","role":"primary"}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"}]},{"id":"01.17","number":"01.17","title":"Burials and Social Difference","paragraphs":[{"id":"01.17-p001","text":"Northern Kyushu adopted burial forms with clear continental connections. Large jars were sometimes covered by heavy stones in dolmen-like arrangements, while stone cists appeared in western Honshu, Kyushu, and the islands of the Korean strait. These forms rarely contained rich goods, but they placed the dead within a wider maritime tradition.","figures":[{"label":"Map 1a","caption":"The map locates Doigahama, Sugu, Mikumo, Ihara, and the main burial forms of western Yayoi communities."},{"label":"Map 1b","caption":"The map shows the Korean and Chinese connections visible in cists, prestige goods, and northern Kyushu exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-016","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.17-p002","text":"Doigahama in Yamaguchi reveals more complex distinctions. Most bodies lay extended with their heads toward the east, but a small group of stone cists occupied the center and alone contained jasper and shell ornaments. Men, women, and children were distributed unevenly through different parts of the cemetery, and tooth modification remained common. Age, sex, kinship, marriage, origin, and rank may all have shaped the pattern, though no single explanation accounts for it.","figures":[{"label":"Map 1a","caption":"The map locates Doigahama, Sugu, Mikumo, Ihara, and the main burial forms of western Yayoi communities."},{"label":"Map 1b","caption":"The map shows the Korean and Chinese connections visible in cists, prestige goods, and northern Kyushu exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-016","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.17-p003","text":"Square-moated graves became especially important in the Kinki and neighboring regions. A wooden coffin or burial lay within a square or rectangular space defined by a ditch, sometimes with additional bodies arranged around it. These graves remained closer to the Yayoi practice of burial below ground than to the monumental mounds that followed, yet they formed part of the architectural ancestry of later tombs.","figures":[{"label":"Map 1a","caption":"The map locates Doigahama, Sugu, Mikumo, Ihara, and the main burial forms of western Yayoi communities."},{"label":"Map 1b","caption":"The map shows the Korean and Chinese connections visible in cists, prestige goods, and northern Kyushu exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-016","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.17-p004","text":"Imported mirrors, glass disks, jade beads, bronze swords, and halberds appeared in or near some northern Kyushu burials. Large concentrations at Ihara, Mikumo, and Sugu reveal communities able to accumulate continental prestige goods and local weapons. Such wealth has encouraged attempts to identify the region with Yamatai, but the finds establish political importance more securely than a specific name.","figures":[{"label":"Map 1a","caption":"The map locates Doigahama, Sugu, Mikumo, Ihara, and the main burial forms of western Yayoi communities."},{"label":"Map 1b","caption":"The map shows the Korean and Chinese connections visible in cists, prestige goods, and northern Kyushu exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-016","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.17-p005","text":"The cemeteries mark an early rise in social height. Objects once acquired through exchange became personal treasures and burial signs, while specialized potters produced enormous jars beyond ordinary household needs. Difference was no longer expressed only through age or ritual role. It was becoming material, accumulative, and inheritable.","figures":[{"label":"Map 1a","caption":"The map locates Doigahama, Sugu, Mikumo, Ihara, and the main burial forms of western Yayoi communities."},{"label":"Map 1b","caption":"The map shows the Korean and Chinese connections visible in cists, prestige goods, and northern Kyushu exchange."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-016","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"}]},{"id":"01.18","number":"01.18","title":"Iron and the Transformation of Work","paragraphs":[{"id":"01.18-p001","text":"A few objects from late Jomon and Early Yayoi contexts have been proposed as the first iron in the archipelago, but the earliest secure examples belong roughly to the second century BC. An iron sword from a wooden coffin near Fukuoka and blade fragments from Kumamoto stand among the oldest finds. Most early pieces were probably imported, and corrosion has erased much of the original record.","figures":[{"label":"Map 1a","caption":"The map locates the earliest iron finds, reported Kyushu furnace sites, and the regions where iron tools spread unevenly."},{"label":"Map 1b","caption":"The map places imported and locally worked iron within the metallurgical routes of Han China and the Korean peninsula."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-017","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.18-p002","text":"The first iron objects reflected continental casting traditions. Forging later spread with Han technological influence and was better suited to the smaller workshops of the archipelago. The sharp rise in Middle Yayoi iron cannot be explained by imported finished tools alone. Local smithing, the search for ore, and the recycling of metal must have expanded.","figures":[{"label":"Map 1a","caption":"The map locates the earliest iron finds, reported Kyushu furnace sites, and the regions where iron tools spread unevenly."},{"label":"Map 1b","caption":"The map places imported and locally worked iron within the metallurgical routes of Han China and the Korean peninsula."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-017","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.18-p003","text":"Iron may have come from Korean sources, but river sands and limonite also offered local material. Primitive furnaces reported in Oita and Miyazaki could refine small batches, though their identification and date require caution. The central change was the movement from possessing iron to knowing how to work it.","figures":[{"label":"Map 1a","caption":"The map locates the earliest iron finds, reported Kyushu furnace sites, and the regions where iron tools spread unevenly."},{"label":"Map 1b","caption":"The map places imported and locally worked iron within the metallurgical routes of Han China and the Korean peninsula."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-017","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.18-p004","text":"By Late Yayoi, iron entered farming, carpentry, fishing, and war. Plows, hoes, sickles, axes, adzes, chisels, planes, hooks, arrowheads, spearheads, swords, and halberds extended the reach of labor. The metal remained unevenly distributed, with few surviving pieces in Kanto and almost none in Tohoku, but absence must be weighed against rapid corrosion.","figures":[{"label":"Map 1a","caption":"The map locates the earliest iron finds, reported Kyushu furnace sites, and the regions where iron tools spread unevenly."},{"label":"Map 1b","caption":"The map places imported and locally worked iron within the metallurgical routes of Han China and the Korean peninsula."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-017","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.18-p005","text":"Wet sites preserve the wooden world shaped by these edges. Excavators have recovered rakes, hoes, loom parts, fire drills, bowls, stools, painted shields, carved birds, human effigies, paddy clogs, and even the body of a koto. In the Kinki, pottery, carved wood, and bronze shared the flowing-water pattern known as ryusui. Iron did not replace wood. It made a new precision in wood possible.","figures":[{"label":"Map 1a","caption":"The map locates the earliest iron finds, reported Kyushu furnace sites, and the regions where iron tools spread unevenly."},{"label":"Map 1b","caption":"The map places imported and locally worked iron within the metallurgical routes of Han China and the Korean peninsula."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-017","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"}]},{"id":"01.19","number":"01.19","title":"Toro and the Managed Landscape","paragraphs":[{"id":"01.19-p001","text":"Toro stood beside the Abe River in present-day Shizuoka. A catastrophic flood ended one phase of the settlement and aligned broken timbers with the flow of the water, preserving the clearest known plan of a mature Yayoi farming village. Few valuables remained, perhaps because the inhabitants escaped with warning or returned to recover them. No iron tools survived, though thousands of regular wooden slats show that iron had shaped the site.","figures":[{"label":"Map 1a","caption":"The map locates Toro, its paddies, water system, raised granaries, and branch settlements."},{"label":"Map 1b","caption":"The map places the mature Yayoi village within the eastward spread of rice agriculture and continental crops."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-toro-settlement-horizon","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-018","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.19-p002","text":"More than fifty paddies occupied about seventy thousand square meters. Ditches, sluices, and wells directed water through the fields, and raised storehouses protected the harvest from damp, insects, and rodents. These buildings stood on heavy posts above the earth and embodied some of the settlement's most advanced carpentry. Their form may stand behind later elevated residences and sacred buildings, though Toro alone cannot establish a direct line from granary to palace or shrine.","figures":[{"label":"Map 1a","caption":"The map locates Toro, its paddies, water system, raised granaries, and branch settlements."},{"label":"Map 1b","caption":"The map places the mature Yayoi village within the eastward spread of rice agriculture and continental crops."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-018","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.19-p003","text":"Houses stood over shallow oval pits on slightly higher ground. Heavy posts rested on buried plates in the soft soil, while thatched roofs, drains, and earthen benches answered a landscape where water was both necessary and dangerous. Regional plans differed, and some southern houses lacked hearths, perhaps because of dampness and warm conditions.","figures":[{"label":"Map 1a","caption":"The map locates Toro, its paddies, water system, raised granaries, and branch settlements."},{"label":"Map 1b","caption":"The map places the mature Yayoi village within the eastward spread of rice agriculture and continental crops."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-018","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.19-p004","text":"Much of the village economy appears to have been collective. Tools were stored together, one granary served several houses, and dwellings stood too close for every household to dry grain independently. Ditches had to be opened, cleared, and repaired according to a common rhythm. The management of ordinary necessity created leadership before any title is known.","figures":[{"label":"Map 1a","caption":"The map locates Toro, its paddies, water system, raised granaries, and branch settlements."},{"label":"Map 1b","caption":"The map places the mature Yayoi village within the eastward spread of rice agriculture and continental crops."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-018","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.19-p005","text":"Population growth sent branch settlements toward higher ground, where wells opened new areas to cultivation. Rice remained central, but millet, beans, peas, barley, wheat, peaches, and gathered fruits broadened the food base. The agricultural village coordinated paddies, dry fields, storage, fishing, and wild resources rather than narrowing life to one grain.","figures":[{"label":"Map 1a","caption":"The map locates Toro, its paddies, water system, raised granaries, and branch settlements."},{"label":"Map 1b","caption":"The map places the mature Yayoi village within the eastward spread of rice agriculture and continental crops."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-018","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"}]},{"id":"01.20","number":"01.20","title":"Conflict and Defended Villages","paragraphs":[{"id":"01.20-p001","text":"Chinese accounts describe wars among the communities of Wa, and archaeology reveals weapons, defensive works, violent injuries, and settlements abandoned in crisis. Stone tools once used in hunting were enlarged or redirected toward combat, especially from the eastern Inland Sea into the Kinki. At Doigahama, a stone arrowhead struck a skull; at Nejiko, a bronze point remained embedded in a woman's head; and several bodies at Yoshinogari were headless.","figures":[{"label":"Map 1a","caption":"The map locates Santonodai, Yoshinogari, Doigahama, and other defended or violently disturbed Yayoi settlements."},{"label":"Map 1b","caption":"The map shows the routes and resource zones over which Yayoi communities competed."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-019","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.20-p002","text":"Some villages occupied heights inconvenient for farming but valuable for defense and control of routes. Santonodai stood on a plateau above Yokohama Bay, enclosed by a ditch and supplied by rice fields near springs below the eastern slope. Houses were rebuilt there from Middle Yayoi into the Yamato period, turning a defensible place into a crowded settlement across generations.","figures":[{"label":"Map 1a","caption":"The map locates Santonodai, Yoshinogari, Doigahama, and other defended or violently disturbed Yayoi settlements."},{"label":"Map 1b","caption":"The map shows the routes and resource zones over which Yayoi communities competed."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-019","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.20-p003","text":"Eight houses burned in one destructive event. Seven were ordinary in size, while one was much larger and contained large pots. Later dwellings held storage pits, and deep shafts at the edge of the plateau may have stored grain for common use. The defended village joined agriculture, collective reserves, and coercive power on one height.","figures":[{"label":"Map 1a","caption":"The map locates Santonodai, Yoshinogari, Doigahama, and other defended or violently disturbed Yayoi settlements."},{"label":"Map 1b","caption":"The map shows the routes and resource zones over which Yayoi communities competed."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-019","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.20-p004","text":"Warfare distinguished allies from enemies and tightened obligations within communities. Competition for land, water, ore, and routes encouraged the formation of larger political centers, particularly around the Kinki and Inland Sea. Growth in production did not bring peace. It raised the value of what could be controlled.","figures":[{"label":"Map 1a","caption":"The map locates Santonodai, Yoshinogari, Doigahama, and other defended or violently disturbed Yayoi settlements."},{"label":"Map 1b","caption":"The map shows the routes and resource zones over which Yayoi communities competed."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-019","role":"primary"}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"}]},{"id":"01.21","number":"01.21","title":"Bronze, Weapons, and Regional Power","paragraphs":[{"id":"01.21-p001","text":"Bronze and iron acquired different social careers. Iron entered ordinary production, while bronze concentrated in mirrors, ornaments, weapons, bells, and public ritual. Casting demanded trained artisans, controlled alloys, molds, and organized access to imported material, making bronze easier to supervise and harder to obtain. Its political force arose from scarcity, brilliance, sound, and controlled display.","figures":[{"label":"Map 1a","caption":"The map distinguishes the western concentration of bronze weapons, the eastern bell zone, and the strategic Kibi corridor."},{"label":"Map 1b","caption":"The map places Yayoi bronze production within maritime supply routes linking Kyushu, Korea, China, and the Inland Sea."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.21-p002","text":"Yayoi bronze finds form two broad zones. Weapons concentrate in northern Kyushu and the western Inland Sea, while bells concentrate from the eastern Inland Sea through the Kinki and into southern Tokai. The zones overlap around Kibi, whose communities controlled the routes between Kyushu and the Kinki. Distribution reveals contact and rivalry, though it does not prove one continuous war between two fixed blocs.","figures":[{"label":"Map 1a","caption":"The map distinguishes the western concentration of bronze weapons, the eastern bell zone, and the strategic Kibi corridor."},{"label":"Map 1b","caption":"The map places Yayoi bronze production within maritime supply routes linking Kyushu, Korea, China, and the Inland Sea."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.21-p003","text":"Bronze swords and spearheads reached northern Kyushu by the first century BC and were soon cast locally, perhaps with immigrant artisans and continental models. Later weapons became longer, wider, and thinner until many were no longer practical. The form of violence had been converted into a ceremonial sign.","figures":[{"label":"Map 1a","caption":"The map distinguishes the western concentration of bronze weapons, the eastern bell zone, and the strategic Kibi corridor."},{"label":"Map 1b","caption":"The map places Yayoi bronze production within maritime supply routes linking Kyushu, Korea, China, and the Inland Sea."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.21-p004","text":"These bronzes were rarely buried with individuals. Groups of swords, spearheads, and halberds were placed together, sometimes arranged by size and perhaps associated with fields, boundaries, or communal protection. The suggestion that they were periodically unearthed and reburied remains possible but unproved. What is secure is that communities removed large quantities of metal from use in deliberate acts.","figures":[{"label":"Map 1a","caption":"The map distinguishes the western concentration of bronze weapons, the eastern bell zone, and the strategic Kibi corridor."},{"label":"Map 1b","caption":"The map places Yayoi bronze production within maritime supply routes linking Kyushu, Korea, China, and the Inland Sea."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-021","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"}]},{"id":"01.22","number":"01.22","title":"Bronze Bells and the Craft of Casting","paragraphs":[{"id":"01.22-p001","text":"The earliest bells were small and resembled Korean horse bells. For a time, scholars assumed that Kyushu imported them without casting them, but mold fragments and workshop debris in Fukuoka and Saga overturned that geography. At Yasunagata, a used bell mold lay with spearhead molds, copper slag, and refined tin, joining several stages of metalworking in one place.","figures":[{"label":"Map 1a","caption":"The map locates Yasunagata, Ibaraki, and the principal workshop and bell-distribution areas."},{"label":"Map 1b","caption":"The map shows how casting knowledge and same-mold bells moved between Kyushu, the Inland Sea, the Kinki, and Shikoku."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.22-p002","text":"Early Inland Sea bells were technically uncertain. Trapped gases scarred their surfaces, flaws were patched, and a few examples carried crude lines resembling faces. By about the second century AD, casters produced sharper relief, cleaner flanges, and more controlled panels. During the third century, bells became taller, thinner, and increasingly standardized.","figures":[{"label":"Map 1a","caption":"The map locates Yasunagata, Ibaraki, and the principal workshop and bell-distribution areas."},{"label":"Map 1b","caption":"The map shows how casting knowledge and same-mold bells moved between Kyushu, the Inland Sea, the Kinki, and Shikoku."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.22-p003","text":"About one bell in ten bears small pictures in thread-like relief. Animals, fish, insects, storehouses, ritual figures, rice pounding, fishing, and hunting with dogs appear within ordered panels. The scenes may have accompanied planting and harvest ceremonies, but their words are lost. The images show which acts of subsistence and ritual were worthy of sacred metal.","figures":[{"label":"Map 1a","caption":"The map locates Yasunagata, Ibaraki, and the principal workshop and bell-distribution areas."},{"label":"Map 1b","caption":"The map shows how casting knowledge and same-mold bells moved between Kyushu, the Inland Sea, the Kinki, and Shikoku."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.22-p004","text":"Identical bells found at distant sites reveal the use of common molds. Several sets include objects from the Kinki, and a nearly complete mold from Ibaraki in Osaka strengthens the case for major foundries around Osaka and Nara. The same workshop also produced molds for curved beads and equipment for bellows. Crafts were concentrated, while finished objects traveled far beyond the place of manufacture.","figures":[{"label":"Map 1a","caption":"The map locates Yasunagata, Ibaraki, and the principal workshop and bell-distribution areas."},{"label":"Map 1b","caption":"The map shows how casting knowledge and same-mold bells moved between Kyushu, the Inland Sea, the Kinki, and Shikoku."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.22-p005","text":"Shared molds prove connection but not the precise political form of that connection. The widening distribution of bells may reflect expanding Kinki influence, exchange among allied communities, or both. Technical standardization and political consolidation were moving together, though neither can be reduced to the other.","figures":[{"label":"Map 1a","caption":"The map locates Yasunagata, Ibaraki, and the principal workshop and bell-distribution areas."},{"label":"Map 1b","caption":"The map shows how casting knowledge and same-mold bells moved between Kyushu, the Inland Sea, the Kinki, and Shikoku."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-020","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"}]},{"id":"01.23","number":"01.23","title":"Buried Bronze and Maritime Supply","paragraphs":[{"id":"01.23-p001","text":"Bronze bells are often found away from houses, on terraces or hillsides above cultivable ground. Some deposits contained several bells; others joined bells with weapons. At Sakuragaoka above Kobe, fourteen bells and seven halberds were concealed together on a wooded ridge. The ceremony is unrecoverable, but carrying, arranging, and surrendering so much metal made burial an act of exceptional public weight.","figures":[{"label":"Map 1a","caption":"The map locates Sakuragaoka and other hillside deposits where bells and weapons were withdrawn from use."},{"label":"Map 1b","caption":"The map places the bronze supply within the maritime circulation of Chinese and Korean metal."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-021","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.23-p002","text":"The quantity of bronze raises the problem of supply. A later chronicle celebrated the discovery of copper in Musashi in 708 through the era name Wado. If substantial local copper had not been available earlier, Yayoi workshops depended on ore, ingots, finished objects, or scrap moving across the sea and then inland. The hundreds of surviving bells and weapons represent only part of the metal once circulating.","figures":[{"label":"Map 1a","caption":"The map locates Sakuragaoka and other hillside deposits where bells and weapons were withdrawn from use."},{"label":"Map 1b","caption":"The map places the bronze supply within the maritime circulation of Chinese and Korean metal."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon","event-wado-copper-discovery-reported"],"illustrationRefs":[{"id":"CH01-IMG-021","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.23-p003","text":"The most plausible sources were Chinese and Korean ore, imported ingots, and finished bronzes melted for reuse. Foreign objects did not retain their first forms. A mirror, vessel, or weapon could be recast as a bell or ceremonial blade suited to a different political and ritual world. Such translation required technical knowledge and authorities able to secure, protect, and distribute scarce material.","figures":[{"label":"Map 1a","caption":"The map locates Sakuragaoka and other hillside deposits where bells and weapons were withdrawn from use."},{"label":"Map 1b","caption":"The map places the bronze supply within the maritime circulation of Chinese and Korean metal."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-021","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.23-p004","text":"Lead-isotope studies compared bronzes from the archipelago with Chinese and Korean ores and mirrors. The tested bells had broadly consistent alloys, and the oldest examples aligned with Korean material, while many others corresponded to Former Han or later Chinese sources. The results support extensive importation but cannot identify the merchants, ports, or agreements behind each movement.","figures":[{"label":"Map 1a","caption":"The map locates Sakuragaoka and other hillside deposits where bells and weapons were withdrawn from use."},{"label":"Map 1b","caption":"The map places the bronze supply within the maritime circulation of Chinese and Korean metal."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-021","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.23-p005","text":"Tin and lead also preserve the history of recasting. Chinese mirrors contained more tin than a Japanese copy, and tested bells and a spearhead contained still less. Repeated heating could alter the alloy while the metal retained an isotopic trace of its origin. The Yayoi bronze economy rested on maritime acquisition, local transformation, and political control.","figures":[{"label":"Map 1a","caption":"The map locates Sakuragaoka and other hillside deposits where bells and weapons were withdrawn from use."},{"label":"Map 1b","caption":"The map places the bronze supply within the maritime circulation of Chinese and Korean metal."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-021","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"}]},{"id":"01.24","number":"01.24","title":"Wa and Himiko","paragraphs":[{"id":"01.24-p001","text":"The fullest external description of late Yayoi society appears in the Chinese history conventionally called the Wei zhi, compiled in the late third century. It describes Wa as a field of many countries, some in direct contact with Chinese commanderies, and names Yamatai as the strongest federation after a period of war. The account is invaluable because it is external and comparatively early, but it is shaped by Chinese diplomatic categories, imperfect reports, and a taste for large round numbers.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai and the principal Wa countries described by the Chinese record."},{"label":"Map 1b","caption":"The map places Himiko within the diplomatic field linking Wa, the Korean commanderies, and the Wei court."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-king-of-na-in-wa-receives-a-han-seal","event-wa-embassy-recorded-at-the-han-court","event-himiko-s-rule-in-yamatai","event-himiko-s-embassy-reaches-wei","event-compilation-of-the-wei-account-of-wa"],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.24-p002","text":"Yamatai was ruled by Himiko, a woman whose authority was represented as both sacred and political. She lived in seclusion, was served by many women, guarded by armed men, and communicated through one brother who assisted in government. The numbers may be conventional, but the structure of secluded ritual authority joined to an administrative intermediary is historically significant.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai and the principal Wa countries described by the Chinese record."},{"label":"Map 1b","caption":"The map places Himiko within the diplomatic field linking Wa, the Korean commanderies, and the Wei court."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.1","caption":"The tree shows Himiko and the unnamed brother through whom her secluded authority entered government.","active":["himiko","himiko_brother"],"row_anchor":{"himiko_brother":"himiko"}}],"timelineRefs":["event-late-yayoi","event-himiko-s-rule-in-yamatai","event-cao-wei-dynasty","event-himiko-s-embassy-reaches-wei","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.24-p003","text":"The account describes markets, tribute or taxation, ranked titles, attendants, and visible gestures of submission between higher and lower people. Men of status were said to have several wives. Professional abstainers accompanied travelers and could be killed if misfortune suggested that they had broken their vows. Divination used burned bones, mourning lasted ten days, and burial took place in a single coffin.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai and the principal Wa countries described by the Chinese record."},{"label":"Map 1b","caption":"The map places Himiko within the diplomatic field linking Wa, the Korean commanderies, and the Wei court."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.24-p004","text":"After Himiko's death, a male successor failed to restore order. Peace returned only when a thirteen-year-old girl was placed in authority. Himiko was said to have been buried in a mound about one hundred meters across with a thousand attendants sacrificed at her death. The scale and immolation figure cannot be accepted literally without corroboration, but the account firmly places female ritual rule, succession crisis, and monumental burial within the political imagination of third-century Wa.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai and the principal Wa countries described by the Chinese record."},{"label":"Map 1b","caption":"The map places Himiko within the diplomatic field linking Wa, the Korean commanderies, and the Wei court."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.1","caption":"The tree separates Himiko's known sibling relation from two successors whose kinship is not stated.","active":["himiko","himiko_brother","male_successor","young_female_successor"],"row_anchor":{"himiko_brother":"himiko","male_successor":"himiko","young_female_successor":"himiko"}}],"timelineRefs":["event-himiko-s-rule-in-yamatai","event-himiko-s-embassy-reaches-wei","event-reported-death-of-himiko","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"}]},{"id":"01.25","number":"01.25","title":"The Road to Yamatai","paragraphs":[{"id":"01.25-p001","text":"The Chinese route begins at Daifang on the Korean peninsula and moves south through Tsushima and Iki to the countries of Matsuura, Ito, Na, and Fumi in northern Kyushu. These first stages can be placed with reasonable confidence. Beyond them, the account gives travel in days by sea and land rather than dependable distances, and the resulting geography has sustained centuries of debate.","figures":[{"label":"Map 1a","caption":"The map traces the recorded route from Daifang through Tsushima, Iki, and northern Kyushu toward the disputed location of Yamatai."},{"label":"Map 1b","caption":"The map shows why continental testimony and later Yamato genealogy produce different geographical and political questions."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-himiko-s-rule-in-yamatai","event-cao-wei-dynasty","event-himiko-s-embassy-reaches-wei","event-compilation-of-the-wei-account-of-wa"],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.25-p002","text":"One influential reading favors a destination in central Japan and treats Yamatai as a Chinese rendering of Yamato. It argued that the long journey beyond northern Kyushu was unnecessary if the destination lay nearby. Other scholars have read the same directions differently, and the location remains disputed. The record securely reveals a route of maritime contact and a powerful federation; it does not securely fix that federation on a modern map.","figures":[{"label":"Map 1a","caption":"The map traces the recorded route from Daifang through Tsushima, Iki, and northern Kyushu toward the disputed location of Yamatai."},{"label":"Map 1b","caption":"The map shows why continental testimony and later Yamato genealogy produce different geographical and political questions."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.25-p003","text":"The dispute became entangled with imperial genealogy. Himiko could not be fitted easily into the lengthened male succession of the Kojiki and Nihon Shoki, and attempts to identify her with the ruler Jingu never resolved the contradictions. Moving Yamatai away from Yamato offered one way to keep the Chinese queen outside the imperial line. The controversy therefore concerns not only distance and direction, but the relation between external testimony and later court memory.","figures":[{"label":"Map 1a","caption":"The map traces the recorded route from Daifang through Tsushima, Iki, and northern Kyushu toward the disputed location of Yamatai."},{"label":"Map 1b","caption":"The map shows why continental testimony and later Yamato genealogy produce different geographical and political questions."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.1","caption":"The Yamatai household remains separate from the later received imperial genealogy.","active":["himiko","himiko_brother"],"row_anchor":{"himiko_brother":"himiko"}},{"id":"G1.2","caption":"The traditional Yamato line places Jingu and Ojin within received court succession, showing why the attempted identification of Himiko with Jingu created chronological and genealogical difficulties.","active":["amaterasu","jimmu","sujin","jingu","ojin"]}],"timelineRefs":["event-himiko-s-rule-in-yamatai","event-compilation-of-the-wei-account-of-wa","event-kojiki-completed","event-nihon-shoki-completed"],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.25-p004","text":"Archaeology confirms several customs described by the Chinese account without proving the location of Yamatai. Burned shoulder bones show divination, simple wooden coffins differ from the nested coffins of wealthy Chinese burials, and the scarcity of chopsticks supports the report that food was eaten by hand. Loom parts and surviving cloth show the production of narrow textiles from silk and plant fibers. External testimony and material evidence meet most securely in ordinary practices rather than in the debated name of a capital.","figures":[{"label":"Map 1a","caption":"The map traces the recorded route from Daifang through Tsushima, Iki, and northern Kyushu toward the disputed location of Yamatai."},{"label":"Map 1b","caption":"The map shows why continental testimony and later Yamato genealogy produce different geographical and political questions."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"}]},{"id":"01.26","number":"01.26","title":"Rank, Trade, and the Fabric of Society","paragraphs":[{"id":"01.26-p001","text":"Chinese descriptions of deference and graded titles agree with archaeological signs of social difference. At Tano in Osaka, larger houses were associated with wooden coffins and grave goods, while smaller dwellings stood near poorer jar burials. Beads, bronze bracelets, nonlocal jasper, and a painted coffin distinguished a few dead from others buried without possessions. The exact social categories are unknown, but equality is no longer a plausible description.","figures":[{"label":"Map 1a","caption":"The map locates Tano, Tateiwa, Imayama, and the production and exchange centers discussed here."},{"label":"Map 1b","caption":"The map shows the circulation of salt, stone, rice, textiles, iron, and southern shells across the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.26-p002","text":"Bronze and textiles may both have strengthened hierarchy. Access to imported metal, skilled workshops, fine cloth, and the routes through which they moved could be controlled and redistributed. Leadership was expressed not only through weapons or ritual, but through the ability to gather goods from distant regions and place them in chosen hands.","figures":[{"label":"Map 1a","caption":"The map locates Tano, Tateiwa, Imayama, and the production and exchange centers discussed here."},{"label":"Map 1b","caption":"The map shows the circulation of salt, stone, rice, textiles, iron, and southern shells across the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.26-p003","text":"Trade linked the archipelago at many scales. Rice appeared in northern sites where it may not have grown, iron reached regions without local ore, and salt-producing settlements made more than their own inhabitants required. Stone reapers from Tateiwa and polished axes from Imayama traveled through northern Kyushu, while wooden tools moved between forest margins and farming plains near Osaka. A man buried at Tateiwa wore fourteen bracelets made from shells whose nearest source lay in the Ryukyu Islands.","figures":[{"label":"Map 1a","caption":"The map locates Tano, Tateiwa, Imayama, and the production and exchange centers discussed here."},{"label":"Map 1b","caption":"The map shows the circulation of salt, stone, rice, textiles, iron, and southern shells across the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.26-p004","text":"These movements do not require a single market system. They reveal overlapping networks of households, specialists, travelers, marriage partners, and political centers. As settlements spread inland, the demand for salt, tools, and imported materials increased. Exchange became part of the structure through which villages survived and leaders distinguished themselves.","figures":[{"label":"Map 1a","caption":"The map locates Tano, Tateiwa, Imayama, and the production and exchange centers discussed here."},{"label":"Map 1b","caption":"The map shows the circulation of salt, stone, rice, textiles, iron, and southern shells across the archipelago."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"}]},{"id":"01.27","number":"01.27","title":"Language, Bodies, and Population","paragraphs":[{"id":"01.27-p001","text":"Older linguistic scholarship treated Japanese as fundamentally related to northern languages, with additional southern elements already present by Yayoi times. Such claims belong to an older linguistic framework and cannot be accepted as settled history. What the historical record does show is that communication across the Korean strait did not erase linguistic difference. By later centuries, interpreters were needed even within immigrant craft communities.","figures":[{"label":"Map 1a","caption":"The map shows the main skeletal regions and the strong demographic concentration developing in Kyushu and the Kinki."},{"label":"Map 1b","caption":"The map places population growth and human movement within the broader East Asian field without implying wholesale replacement."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.27-p002","text":"Human remains offer firmer, though still incomplete, evidence for population change. About a thousand Yayoi skeletons were known from southwestern Japan, many preserved in burial jars. Early Yayoi people in northern and western Kyushu were on average somewhat taller than Jomon predecessors but otherwise often similar. The evidence does not support a single invading population replacing everyone already present.","figures":[{"label":"Map 1a","caption":"The map shows the main skeletal regions and the strong demographic concentration developing in Kyushu and the Kinki."},{"label":"Map 1b","caption":"The map places population growth and human movement within the broader East Asian field without implying wholesale replacement."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.27-p003","text":"Differences became clearer toward the end of Yayoi. Faces grew flatter in many samples, stature and skull form varied by region, and nutrition affected growth, teeth, and longevity. Some older studies divided weapon-burying and bell-burying populations too sharply by skull shape. Regional ancestry mattered, but food, labor, disease, and marriage could transform bodies within a few generations.","figures":[{"label":"Map 1a","caption":"The map shows the main skeletal regions and the strong demographic concentration developing in Kyushu and the Kinki."},{"label":"Map 1b","caption":"The map places population growth and human movement within the broader East Asian field without implying wholesale replacement."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-yayoi"],"mapPlacement":"after-paragraph"},{"id":"01.27-p004","text":"Population rose dramatically. Older estimates counted more than ten thousand Yayoi sites and placed the total population at roughly six hundred thousand, several times that of Latest Jomon. The figures are approximate, but the direction is secure. Rice agriculture and mixed farming supported denser settlement, while stable occupation was especially marked in the Kinki. The Osaka-Nara region offered fertile plains, protected basins, and access to inland and maritime routes. Its later political importance rested on this long accumulation of people and place.","figures":[{"label":"Map 1a","caption":"The map shows the main skeletal regions and the strong demographic concentration developing in Kyushu and the Kinki."},{"label":"Map 1b","caption":"The map places population growth and human movement within the broader East Asian field without implying wholesale replacement."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi","event-late-yayoi","event-early-kofun-horizon"],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"}]},{"id":"01.28","number":"01.28","title":"Jimmu and the Kinki","paragraphs":[{"id":"01.28-p001","text":"The chronicles place the expedition of Jimmu within a world of competing Yayoi chieftains. He travels from southern Kyushu through the Inland Sea, overcomes resistance in Kibi, fails to enter the Kinki directly from Osaka, and reaches the Nara basin by circling to the east. The account is not a securely dated campaign, but its geography reflects enduring political facts: the strategic weight of Kibi, the strength of the Kinki approaches, and the attraction of the lower Nara basin.","figures":[{"label":"Map 1a","caption":"The map traces the traditional Jimmu route from southern Kyushu through Kibi to the Nara basin."},{"label":"Map 1b","caption":"The map places the chronicle expedition beside the archaeological rise of Kinki power in the second and third centuries AD."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree places Jimmu within traditional descent from Amaterasu rather than contemporary political genealogy.","active":["amaterasu","jimmu"]}],"timelineRefs":["event-final-jomon","event-initial-and-early-yayoi-northern-kyushu","event-traditional-accession-of-jimmu","event-middle-yayoi"],"illustrationRefs":[{"id":"CH01-IMG-023","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.28-p002","text":"At moments of danger, Jimmu seeks counsel from kami, performs abstinence and sacrifice, and resumes the advance. The story makes ritual mediation inseparable from command. Chinese descriptions of shamanic rulers, archaeological evidence for warfare, and the rise of a strong third-century center in the Kinki do not prove the chronicle narrative, but they make its political world intelligible.","figures":[{"label":"Map 1a","caption":"The map traces the traditional Jimmu route from southern Kyushu through Kibi to the Nara basin."},{"label":"Map 1b","caption":"The map places the chronicle expedition beside the archaeological rise of Kinki power in the second and third centuries AD."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-late-yayoi","event-himiko-s-rule-in-yamatai","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-023","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.28-p003","text":"The later court used Jimmu to express a foundation that joined conquest, migration, and divine authorization. His genealogy belongs to sacred memory, while the growth of Kinki power belongs to archaeology. The two witnesses should be heard together without being mistaken for the same voice.","figures":[{"label":"Map 1a","caption":"The map traces the traditional Jimmu route from southern Kyushu through Kibi to the Nara basin."},{"label":"Map 1b","caption":"The map places the chronicle expedition beside the archaeological rise of Kinki power in the second and third centuries AD."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree distinguishes sacred descent from the archaeological rise of Kinki power.","active":["amaterasu","jimmu"]}],"illustrationRefs":[{"id":"CH01-IMG-023","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"}]},{"id":"01.29","number":"01.29","title":"Izumo and Kojindani","paragraphs":[{"id":"01.29-p001","text":"The Kojiki and Nihon Shoki remember Izumo as a formidable rival that had to be brought into the Yamato order. Later interpretation often accepted the court's hostile image of the region as remote, dark, and resistant. Archaeology has made that dismissal impossible.","figures":[{"label":"Map 1a","caption":"The map locates Kojindani, the Hii River, Lake Shinji, and the sacred and political landscape of Izumo."},{"label":"Map 1b","caption":"The map places Izumo within western maritime routes and the regional centers competing with Yamato."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree shows the traditional Izumo branch descending from Susa no O toward Okuni Nushi.","active":["susa_no_o","okuni_nushi"]}],"illustrationRefs":[{"id":"CH01-IMG-024","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.29-p002","text":"At Kojindani in Shimane, a road project uncovered a cache of three hundred fifty-eight bronze swords, sixteen spearheads, and six bells. The number of swords exceeded the total then known from the rest of the archipelago. They lay on a slope above the Hikawa plain, near the Hii River, Lake Shinji, ancient burial mounds, and the wider sacred landscape of Izumo.","figures":[{"label":"Map 1a","caption":"The map locates Kojindani, the Hii River, Lake Shinji, and the sacred and political landscape of Izumo."},{"label":"Map 1b","caption":"The map places Izumo within western maritime routes and the regional centers competing with Yamato."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-middle-yayoi","event-kojindani-bronze-deposition-horizon","event-late-yayoi","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-024","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.29-p003","text":"The swords are remarkably uniform, mostly between fifty and fifty-three centimeters long, and may have been produced locally or under highly coordinated conditions. They were placed in four ordered rows within an oblong pit. Most points faced east, while a dark organic layer above them may preserve a cloth covering and nearby postholes suggest a light structure.","figures":[{"label":"Map 1a","caption":"The map locates Kojindani, the Hii River, Lake Shinji, and the sacred and political landscape of Izumo."},{"label":"Map 1b","caption":"The map places Izumo within western maritime routes and the regional centers competing with Yamato."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-024","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.29-p004","text":"The deposit proves an exceptional concentration of metal, labor, and ceremony. It does not identify a ruler or make the myths direct reports of Kojindani. It does show that Yamato's later insistence on Izumo's submission grew beside a western center of real wealth and organized power. Maritime exchange with Korea may have contributed to that strength, though the routes remain uncertain.","figures":[{"label":"Map 1a","caption":"The map locates Kojindani, the Hii River, Lake Shinji, and the sacred and political landscape of Izumo."},{"label":"Map 1b","caption":"The map places Izumo within western maritime routes and the regional centers competing with Yamato."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-024","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"}]},{"id":"01.30","number":"01.30","title":"Myth, Submission, and Sacred Authority","paragraphs":[{"id":"01.30-p001","text":"Court mythology sends Susa no O, the brother of Amaterasu, from the heavenly community to the bank of the Hii River. There he kills the eight-headed serpent and establishes himself in Izumo. His descendant Okuni Nushi becomes the principal rival of the heavenly line and must surrender authority before Yamato's sacred order can begin.","figures":[{"label":"Map 1a","caption":"The map locates Izumo, Tsukushi, Kibi, and Yamato within the sacred geography arranged by the court chronicles."},{"label":"Map 1b","caption":"The map shows the regional bronze traditions and alliances later recast as divine descent and political submission."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree sets the sibling branches of Amaterasu and Susa no O behind the court opposition of Yamato and Izumo.","active":["amaterasu","susa_no_o","okuni_nushi","jimmu"]}],"timelineRefs":["event-kojindani-bronze-deposition-horizon","event-kojiki-completed","event-nihon-shoki-completed"],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.30-p002","text":"Okuni Nushi appears under several regional names and is also called Yachihoko, the deity of countless spears. The dense weapon imagery may preserve memories of Yayoi ritual and political life, but no bronze deposit can identify a figure in myth. The stories are strongest as evidence for how later Yamato arranged its relation to rival sacred centers.","figures":[{"label":"Map 1a","caption":"The map locates Izumo, Tsukushi, Kibi, and Yamato within the sacred geography arranged by the court chronicles."},{"label":"Map 1b","caption":"The map shows the regional bronze traditions and alliances later recast as divine descent and political submission."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree places Okuni Nushi within the Izumo branch and the heavenly line behind Yamato.","active":["amaterasu","susa_no_o","okuni_nushi","jimmu"]}],"illustrationRefs":[{"id":"CH01-IMG-024","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.30-p003","text":"In the settlement narrated by the chronicles, Okuni Nushi receives a great palace and continuing honor in exchange for withdrawal from political rule. Izumo retains religious responsibility, while the descendants of Amaterasu claim government. Conquest is recast as a division of sacred and political authority. The special oath later required of Izumo's governor and the continuing importance of the Great Shrine preserved the memory that this submission was never ordinary.","figures":[{"label":"Map 1a","caption":"The map locates Izumo, Tsukushi, Kibi, and Yamato within the sacred geography arranged by the court chronicles."},{"label":"Map 1b","caption":"The map shows the regional bronze traditions and alliances later recast as divine descent and political submission."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree clarifies how rival sacred descent was converted into a division of ritual and political authority.","active":["amaterasu","susa_no_o","okuni_nushi","jimmu"]}],"timelineRefs":["event-kojindani-bronze-deposition-horizon","event-kojiki-completed","event-nihon-shoki-completed"],"illustrationRefs":[{"id":"CH01-IMG-024","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.30-p004","text":"Northern Kyushu formed another center, rich in bronze weapons and continental connections. One older reconstruction connected this spear tradition with the sun-spear imagery of myth and imagined an eastward movement of male chieftains into regions associated with bells and female sacred authority. The correspondence is suggestive but too exact to be secure. What can be seen is recombination: weapons, bells, mirrors, immigrant techniques, regional rites, and expanding alliances were gathered into new symbols of rule.","figures":[{"label":"Map 1a","caption":"The map locates Izumo, Tsukushi, Kibi, and Yamato within the sacred geography arranged by the court chronicles."},{"label":"Map 1b","caption":"The map shows the regional bronze traditions and alliances later recast as divine descent and political submission."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"}]},{"id":"01.31","number":"01.31","title":"Women, Sujin, and Dynastic Memory","paragraphs":[{"id":"01.31-p001","text":"Himiko shows that female ritual authority could stand at the center of a third-century federation. The Yamato chronicles likewise placed Amaterasu, a female deity, above the ancestral order of the ruling house. Yet they organized earthly succession through an extended male genealogy whose earliest reigns lack independent dates, acts, or inscriptions.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai, Yamato, Tenri, and the early keyhole-tomb region of the Nara basin."},{"label":"Map 1b","caption":"The map places Himiko, traditional dynastic memory, and the Kofun transition within third-century East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.1","caption":"The tree shows female rule in Yamatai through Himiko's political household.","active":["himiko","himiko_brother"],"row_anchor":{"himiko_brother":"himiko"}},{"id":"G1.2","caption":"The traditional tree places Amaterasu above a received line that later includes Jingu and Ojin, without identifying Jingu with Himiko.","active":["amaterasu","jimmu","sujin","jingu","ojin"]}],"timelineRefs":["event-late-yayoi","event-himiko-s-rule-in-yamatai","event-reported-death-of-himiko","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-wa"],"mapPlacement":"after-paragraph"},{"id":"01.31-p002","text":"Later compilers had reason to enlarge the antiquity and continuity of the male line, while later historians sharpened it further. This made Himiko difficult to place and encouraged both her identification with Jingu and the removal of Yamatai from Yamato. Neither solution should be treated as established. Female shamans, brothers, male chieftains, mothers, and sacred ancestors all participated in early authority. The evidence does not describe a simple passage from matriarchy to patriarchy.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai, Yamato, Tenri, and the early keyhole-tomb region of the Nara basin."},{"label":"Map 1b","caption":"The map places Himiko, traditional dynastic memory, and the Kofun transition within third-century East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The expanded traditional line makes visible the later court position of Jingu and Ojin while keeping them separate from Himiko's externally reported household.","active":["amaterasu","jimmu","sujin","jingu","ojin"]}],"illustrationRefs":[{"id":"CH01-IMG-022","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.31-p003","text":"Mimaki-iri-biko-inie, later called Sujin, stands tenth in the received sequence. The Kojiki says that he first ruled the land, marking him as a beginning even within court tradition. The competing dates assigned to his death are uncertain, but he is often treated as the earliest ruler around whom substantial Yamato memory gathers.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai, Yamato, Tenri, and the early keyhole-tomb region of the Nara basin."},{"label":"Map 1b","caption":"The map places Himiko, traditional dynastic memory, and the Kofun transition within third-century East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree locates Sujin after Jimmu within the abbreviated received chronology.","active":["jimmu","sujin"]}],"timelineRefs":["event-traditional-reign-of-sujin","event-late-yayoi","event-himiko-s-rule-in-yamatai","event-standardized-keyhole-kofun"],"illustrationRefs":[{"id":"CH01-IMG-025","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"},{"id":"01.31-p004","text":"A large keyhole tomb south of Tenri has traditionally been assigned to Sujin. The personal identification cannot be proved, but the tomb form belongs to the late third or early fourth century, when monumental keyhole mounds appeared in the Nara basin and spread through political networks. Sujin therefore stands at the boundary between traditional genealogy and the archaeological horizon of the Kofun age.","figures":[{"label":"Map 1a","caption":"The map locates Yamatai, Yamato, Tenri, and the early keyhole-tomb region of the Nara basin."},{"label":"Map 1b","caption":"The map places Himiko, traditional dynastic memory, and the Kofun transition within third-century East Asia."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"genealogy":[{"id":"G1.2","caption":"The tree keeps Sujin's traditional position distinct from the archaeological dating of keyhole tombs.","active":["jimmu","sujin"]}],"timelineRefs":["event-late-yayoi","event-himiko-s-rule-in-yamatai","event-standardized-keyhole-kofun"],"illustrationRefs":[{"id":"CH01-IMG-025","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"}]},{"id":"01.32","number":"01.32","title":"From Paleolithic Adaptation to Yamato","paragraphs":[{"id":"01.32-p001","text":"Claims for occupation before thirty-five thousand BC remain disputed, but from about thirty thousand years ago the Paleolithic record becomes widespread and regionally varied. Mobile communities adapted stone technology to changing animals, plants, climates, and volcanic landscapes. Rapid warming and rising seas then transformed subsistence, and pottery, the bow, coastal foods, and shell mounds formed the basis of early Jomon life.","figures":[{"label":"Map 1a","caption":"The map traces the long movement from Paleolithic settlement through Jomon regional worlds to Yayoi federations and Yamato."},{"label":"Map 1b","caption":"The map places the archipelago within the continental and maritime relations that shaped every stage of the chapter."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-late-pleistocene","event-upper-paleolithic-in-japan","event-last-glacial-maximum","event-incipient-jomon-mesolithic-transition","event-early-holocene"],"mapRefs":["map-1-paleolithic"],"mapPlacement":"after-paragraph"},{"id":"01.32-p002","text":"Jomon history was not a pause before agriculture. Early warming supported a great rise in coastal population, while Middle Jomon communities built large highland settlements around springs, forest harvests, storage, craft, and the central hearth. When repeated rains weakened that economy, people moved toward coasts and lower valleys, carrying pottery, ritual practice, and exchange into new regional combinations.","figures":[{"label":"Map 1a","caption":"The map traces the long movement from Paleolithic settlement through Jomon regional worlds to Yayoi federations and Yamato."},{"label":"Map 1b","caption":"The map places the archipelago within the continental and maritime relations that shaped every stage of the chapter."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-incipient-jomon-mesolithic-transition","event-initial-jomon","event-early-jomon","event-middle-jomon","event-late-jomon","event-final-jomon"],"illustrationRefs":[{"id":"CH01-IMG-010","role":"primary"}],"mapRefs":["map-1-late-jomon"],"mapPlacement":"after-paragraph"},{"id":"01.32-p003","text":"By Latest Jomon, the largest concentrations lay in the north, while northern Kyushu entered an agricultural transition. Rice cultivation began before the old pottery sequence had ended. Wet fields, dry crops, fishing, and gathering coexisted, and immigrants joined existing populations rather than replacing them in one movement.","figures":[{"label":"Map 1a","caption":"The map traces the long movement from Paleolithic settlement through Jomon regional worlds to Yayoi federations and Yamato."},{"label":"Map 1b","caption":"The map places the archipelago within the continental and maritime relations that shaped every stage of the chapter."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-late-jomon","event-final-jomon","event-initial-and-early-yayoi-northern-kyushu","event-middle-yayoi"],"mapRefs":["map-1-rice"],"mapPlacement":"after-paragraph"},{"id":"01.32-p004","text":"Iron and bronze arrived through continental and peninsular connections, but communities within the archipelago selected, copied, enlarged, recast, and ritualized them differently. Agriculture supported larger villages, storage, specialization, and stronger claims over land and water. Moats, weapons, wounded bodies, and Chinese reports show that the same growth intensified conflict.","figures":[{"label":"Map 1a","caption":"The map traces the long movement from Paleolithic settlement through Jomon regional worlds to Yayoi federations and Yamato."},{"label":"Map 1b","caption":"The map places the archipelago within the continental and maritime relations that shaped every stage of the chapter."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"illustrationRefs":[{"id":"CH01-IMG-025","role":"primary"}],"mapRefs":["map-1-bronze"],"mapPlacement":"after-paragraph"},{"id":"01.32-p005","text":"Federations emerged in northern Kyushu, along the Inland Sea, in Izumo, and in the Kinki. Weapons and mirrors were prominent in the west, bells farther east, though the zones overlapped. By the third century, the Nara basin sustained a center able to gather agricultural wealth, ritual authority, military force, and continental connections. The Yamato state did not arise from an empty country or an inevitable national destiny. It emerged from the long convergence of regional societies, and its new scale of power became visible in the immense mounds of the Kofun age.","figures":[{"label":"Map 1a","caption":"The map traces the long movement from Paleolithic settlement through Jomon regional worlds to Yayoi federations and Yamato."},{"label":"Map 1b","caption":"The map places the archipelago within the continental and maritime relations that shaped every stage of the chapter."},{"label":"Map 1.2","caption":"The source map locates major Yayoi sites and the broad concentration zones of bronze weapons and bells; its OCR labels remain provisional."}],"timelineRefs":["event-late-yayoi","event-himiko-s-rule-in-yamatai","event-early-kofun-horizon"],"illustrationRefs":[{"id":"CH01-IMG-025","role":"primary"}],"mapRefs":["map-1-memory"],"mapPlacement":"after-paragraph"}]}],"compiler":{"chapter":"ch01","sources":{"text":"H:\\Ancient Japan History\\ch01\\ch01_text.txt","mediaMapping":"H:\\Ancient Japan History\\ch01\\ch01_media_mapping.txt","genealogy":"H:\\Ancient Japan History\\ch01\\ch01_genealogy.txt","mapMapping":"H:\\Ancient Japan History\\gis\\documentation\\ch01_map_mapping.txt","illustrationMapping":"H:\\Ancient Japan History\\ch01\\ch01_illustrations_map.txt","illustrationPlan":"H:\\Ancient Japan History\\ch01\\ch01_image_prompts.txt"}}};
